/** 统一 package.json 模板（peerDeps 范围声明，不硬编码版本）。 */
function scaffoldPackageJson(pkgName: string, description: string, form: string): string {
  const withClient = form === 'ui-panel' || form === 'hybrid'
  const peerDeps: Record<string, string> = {
    '@deepseek-ai/dsh-llm': '>=0.0.1-rc <2',
    '@deepseek-ai/dsh-tools': '>=0.0.1-rc <2',
    'cordis': '>=4.0.0-rc <5',
    '@deepseek-ai/schemastery': '^3.18.2',
  }
  if (withClient) {
    peerDeps['@deepseek-ai/dsh-client-ui-slots'] = '>=0.0.1-rc <2'
  }
  const pkg: Record<string, unknown> = {
    name: pkgName,
    version: '0.0.1',
    description: description || pkgName + '（' + form + ' 形态）',
    private: true,
    type: 'module',
    main: './lib/index.js',
    types: './lib/types/index.d.ts',
    files: ['lib'],
    license: 'BSD-3-Clause',
    peerDependencies: peerDeps,
    devDependencies: {
      '@types/node': '^24.13.3',
      typescript: '^5.9.0',
    },
    scripts: {
      build: 'bash scripts/build.sh',
      typecheck: 'tsc -p tsconfig.json --noEmit',
    },
  }
  if (withClient) {
    ;(pkg.devDependencies as Record<string, string>)['tsdown'] = '^0.22.14'
    ;(pkg.scripts as Record<string, string>)['build:client'] = 'tsdown'
    ;(pkg as Record<string, unknown>).exports = {
      '.': { types: './lib/types/index.d.ts', default: './lib/index.js' },
      './client': { types: './lib/types/client/index.d.ts', default: './lib/client.js' },
      './package.json': './package.json',
    }
    ;(pkg as Record<string, unknown>).dsh = {
      client: { inject: ['@deepseek-ai/dsh-client-runtime', '@deepseek-ai/dsh-client-ui-slots'], platform: 'web' },
    }
  }
  return JSON.stringify(pkg, null, 2) + '\n'
}

type AppContext = Context & {
  loader: Loader
  tools: ToolRegistry
  systemPrompt: SystemPrompt
  webServer: any
  registry: any
  setInterval(fn: () => void, ms: number): any
}

export const name = 'dsh-super-injector'
export const inject = ['loader', 'timer', 'tools', 'systemPrompt', 'webServer']

export interface Config {
  /** 注入清单文件路径（缺省 ~/.dsh/super-injector/registry.json）。 */
  registryFile: string
  /** junction 链接目标目录（缺省 ~/.dsh/profiles/web/node_modules）。 */
  profileNodeModules: string
  /** 启动时自动恢复清单中的注入。 */
  autoRestore: boolean
  /** 轮询间隔（ms）。构建产物整批写入，间隔轮询天然合并抖动。 */
  intervalMs: number
  /** 监听目录 → 缓存匹配子串（loadCache key 是 realpath，用目录名匹配）。 */
  watches: Array<{ dir: string; match: string }>
}

// 显式标注为 Config 接口：junction 化依赖（vendor/cosmokit 等）会让推断类型
// 引用非便携绝对路径，declaration 编译报 TS2742。schemastery 的 Schema 类型
// 未导出，直接断言到本包接口（loader 侧只做校验，运行类型语义不变）。
export const Config = z.object({
  registryFile: z.string().default(''),
  profileNodeModules: z.string().default(''),
  autoRestore: z.boolean().default(true),
  intervalMs: z.number().default(1500),
  watches: z.array(z.object({
    dir: z.string().required(),
    match: z.string().required(),
  })).default([]),
}) as unknown as Config

interface RegistryEntry {
  dir: string
  name: string
  at: string
}

const FIBER_NAMES = ['pending', 'loading', 'active', 'failed', 'disposed', 'unloading']

/** 递归收集 dir 下所有 .js 的相对路径指纹（mtime + size）。
 * E: 只统计 .js（运行时文件）——跳过 .map/.d.ts（构建产物，不参与运行，
 * 通常占一半以上）——正确性不变，stat 开销省 50%+。
 * （实测：Windows 上改文件内容不更新父目录 mtime，目录级快路径不可用，
 * 故保留全量 .js 深扫，仅收窄文件范围。） */
function fingerprintOf(dir: string): string | null {
  try {
    const parts: string[] = []
    const walk = (base: string) => {
      for (const entry of readdirSync(base, { withFileTypes: true })) {
        const full = join(base, entry.name)
        if (entry.isDirectory()) {
          walk(full)
        } else if (entry.name.endsWith('.js') && !entry.name.endsWith('.d.ts')) {
          const st = statSync(full)
          parts.push(`${relative(dir, full)}:${st.mtimeMs}:${st.size}`)
        }
      }
    }
    walk(dir)
    parts.sort()
    return parts.join('|')
  } catch {
    return null
  }
}

/**
 * 操作互斥锁：注入/卸载/重载/安装全部串行执行（多会话并发调用注入器时，
 * 后操作排队等前操作完成——避免同一插件被并发重载/卸载的竞态）。
 */
let opChain: Promise<unknown> = Promise.resolve()
function withOpLock<T>(fn: () => Promise<T> | T): Promise<T> {
  const run = opChain.then(() => fn(), () => fn())
  opChain = run.then(() => undefined, () => undefined)
  return run
}

export function apply(ctx: AppContext, config: Config): void {
  const logger = ctx.logger
  // ⚠️ DSH_HOME 优先（实测踩坑）：部署的 web 进程 homedir 可能与 DSH_HOME 指向
  // 不同用户（如服务账户/另一用户 profile），homedir() 推导的路径会全部错位——
  // junction 建到错误 profile、loader 找不到包。DSH_HOME 环境变量才是权威。
  const dshHome = process.env.DSH_HOME || join(homedir(), '.dsh')
  const registryFile = config.registryFile || join(dshHome, 'super-injector', 'registry.json')
  const profileNodeModules = config.profileNodeModules || join(dshHome, 'profiles', 'web', 'node_modules')
  // 热重载的 config 合并路径可能缺 schema 新字段（旧 fiber _config + patch 旧值），
  // 防御性兜底（schema 默认值只在 loader 装配时保证）。
  const intervalMs = config.intervalMs ?? 1500
  const watches = config.watches ?? []

  // ============ 注入清单 ============
  function readRegistry(): RegistryEntry[] {
    try {
      const list = JSON.parse(readFileSync(registryFile, 'utf8'))
      return Array.isArray(list) ? list : []
    } catch {
      return []
    }
  }

  function writeRegistry(list: RegistryEntry[]): void {
    mkdirSync(dirname(registryFile), { recursive: true })
    // 原子写：先 tmp 再 rename，避免中途崩溃留下半截 JSON 毒化下次恢复。
    const tmp = registryFile + '.tmp'
    writeFileSync(tmp, JSON.stringify(list, null, 2), 'utf8')
    renameSync(tmp, registryFile)
  }

  /** 该包是否已有 ACTIVE 的 loader entry（权威防重判断）。 */
  function hasActiveEntry(pkgName: string): boolean {
    for (const entry of ctx.loader.entries()) {
      const opts = entry.options
      if (opts.group) continue
      if (opts.name === pkgName && entry.fiber && FIBER_NAMES[entry.fiber.state] === 'active') return true
    }
    return false
  }

  /** 清除某包目录的模块缓存残留（失败 import 留下的残缺 job 会毒化重试）。 */
  function purgeCache(pkgDir: string): void {
    const loadCache = ctx.loader.internal?.loadCache as Map<string, unknown> | undefined
    if (!loadCache || typeof loadCache.delete !== 'function') return
    const key = pkgDir.replace(/\\/g, '/')
    for (const u of [...loadCache.keys()]) {
      // URL 是百分号编码的（非 ASCII 目录），先解码再匹配
      const uDecoded = decodeURIComponent(u)
      if (uDecoded.includes(key)) Map.prototype.delete.call(loadCache, u)
    }
  }

  // ============ 热重载核心 ============
  /** 按包名匹配清理 webserver 路由残留（强制登记守卫的自愈部分）。 */
  function clearRoutesByMatch(match: string): string[] {
    const hs = ctx.webServer
    const cleaned: string[] = []
    for (const tableName of ['exact', 'prefixes', 'upgrades'] as const) {
      const table = hs?.[tableName]
      if (!table || typeof table.delete !== 'function') continue
      for (const k of [...table.keys()]) {
        if (String(k).includes(match)) {
          table.delete(k)
          cleaned.push(`${tableName}[${k}]`)
        }
      }
    }
    return cleaned
  }

  /**
   * 整包热重载：清缓存 → import → 重建 fiber，失败回滚保留旧代。
   * @param match - entry 匹配子串（id/name；同时用于 URL 匹配，除非给 urlMatch）
   * @param urlMatch - URL 匹配子串（watch 自动重载传目录路径；loadCache key 是
   *   百分号编码的 file URL，包名不是 URL 子串，必须用目录路径匹配）
   */

  // ═══ 自重载保护（防自毁）═══
  // 自重载 = 注入器 dispose 自己 → 全局定时器重建。风险面：
  // ① 短名误匹配（match='super'）会绕过 isSelf 走普通重载路径——普通路径在
  //    dispose 自身 fiber 后继续执行必然炸（inactive context），等于自杀且无
  //    重启器兜底——必须强制收敛到 isSelf 分支或拒绝；
  // ② 连环自杀：无节流时自重载可被反复触发（含失败重试）——最小间隔锁；
  // ③ watch 自动重载不应触发自重载（改注入器代码 → build → 自动自杀，无人
  //    在场时注入器可能永久缺席）——watch 轮询显式跳过注入器自身。
  const SELF_RELOAD_MIN_INTERVAL_MS = 10_000 // 自重载最小间隔（防连环自杀）
  let selfReloading = false                    // 自杀→重建窗口锁（窗口内拒绝再次触发）
  // ⚠️ 节流时间戳必须落盘：重启器重建 = 新 fiber = 新闭包，内存变量会归零
  // （实测连续三次自重载都没被拦）。文件状态跨实例持久。
  const selfReloadStateFile = join(dirname(registryFile), 'self-reload.json')

  function readSelfReloadState(): { at: number } {
    try {
      const raw = JSON.parse(readFileSync(selfReloadStateFile, 'utf8')) as { at?: number }
      return { at: typeof raw.at === 'number' ? raw.at : 0 }
    } catch {
      return { at: 0 }
    }
  }

  function writeSelfReloadState(at: number): void {
    try {
      mkdirSync(dirname(selfReloadStateFile), { recursive: true })
      writeFileSync(selfReloadStateFile, JSON.stringify({ at }, null, 2), 'utf8')
    } catch { /* 状态写失败不阻塞（退化为窗口锁保护） */ }
  }

  /** 目标 entry 名是否命中注入器自身（match 或匹配 entry 含注入器名）。 */
  function matchesSelf(match: string): boolean {
    if (String(match).includes('dsh-super-injector')) return true
    for (const entry of ctx.loader.entries()) {
      const o = entry.options
      if (o.group) continue
      if (!String(o.name).includes('dsh-super-injector')) continue
      if (String(o.name).includes(match) || String(o.id).includes(match)) return true
    }
    return false
  }

  // ═══ 故障审计（消除不确定性）：自重载失败/自愈尝试全程落盘 self-heal.log。
  // 教训（实测）：失败只写 logger（harness 终端不可见），恢复后 agent 只能靠
  // 工具在不在猜测根因——多轮试错。落盘后：恢复即查日志，根因可复盘。
  const selfHealLogFile = join(dirname(registryFile), 'self-heal.log')

  /** 追加一行故障审计（时间 + 事件 + 详情）。 */
  function auditLog(event: string, detail: string): void {
    try {
      mkdirSync(dirname(selfHealLogFile), { recursive: true })
      rotateLog(selfHealLogFile)
      appendFileSync(selfHealLogFile, `[${new Date().toISOString()}] ${event}: ${detail}\n`)
    } catch { /* 审计写失败不阻塞 */ }
  }

  /** 日志轮转（D）：超限后滚动 .1/.2，保留 2 代，防长期运行无限增长。 */
  function rotateLog(file: string): void {
    try {
      const st = statSync(file)
      if (st.size <= 1024 * 1024) return
      try { rmSync(file + '.2', { force: true }) } catch { /* 忽略 */ }
      try { renameSync(file + '.1', file + '.2') } catch { /* 忽略 */ }
      try { renameSync(file, file + '.1') } catch { /* 忽略 */ }
    } catch { /* 文件不存在等，忽略 */ }
  }

  /**
   * ═══ 统一 profile patch 写入（F：防 YAML 双顶层值 + 防重复 id——实测踩坑）═══
   * 官方 patch 初始是顶层 `[]`（空数组）；盲 append `- id:` 会产生两个顶层
   * YAML 值 → 解析必炸。本函数：移除顶层 `[]` 再追加条目，保证文件始终
   * 单一顶层值（列表）。
   *
   * ═══ 幂等去重（2026-08-15 别人机器 duplicate loader entry id 教训）═══
   * 手动 patch / 重复安装 / 多路径写入都可能让同 id entry 出现两次——dsh
   * loader 装配遇同 id 直接抛 `duplicate loader entry id`，整个 plugin tree
   * 加载失败（启动即崩），且注入器自身无法自愈（鸡生蛋）。因此：
   *  1. 写入前扫描现有条目 id；若 appendText 的 id 已存在 → 不追加（幂等）；
   *  2. 对历史重复：重写文件时按 id 去重（保留最后一条，注释块保留）；
   *  3. heal/self-test 等触碰 patch 的路径全部走这里，杜绝盲 append。
   * @param appendText - 要追加的条目文本（含换行，如 `- id: xxx\n  disabled: true\n`）
   * @returns 是否发生了写入
   */
  function writePatch(appendText: string): boolean {
    try {
      const patchFile = join(dirname(profileNodeModules), 'cordis.patch.yml')
      mkdirSync(dirname(patchFile), { recursive: true })
      let content = ''
      try { content = readFileSync(patchFile, 'utf8') } catch { /* 不存在按空处理 */ }
      // 1. 收集 appendText 携带的 id（支持单条 `- id: x` 与 `- insert:` 包裹块）
      const appendIds = [...appendText.matchAll(/^\s*- id:\s*([^\s#]+)/gm)].map((m) => m[1])
      // 2. 提取现有内容里所有条目块（含注释），按 id 归组
      const blocks = extractPatchBlocks(content)
      const existing = new Set<string>()
      const kept: string[] = []
      for (const b of blocks) {
        if (b.id) {
          // 同 id 重复：只保留最后一条（后续同名覆盖先前的）
          if (existing.has(b.id)) continue
          existing.add(b.id)
        }
        kept.push(b.text)
      }
      // 3. 幂等：appendIds 全部已存在 → 不写入
      if (appendIds.length > 0 && appendIds.every((id) => existing.has(id))) {
        return false
      }
      // 4. 重写：去重后的现有块 + 追加文本
      const cleanedTop = kept.join('').replace(/^\s*\[\]\s*$/m, '')
      writeFileSync(patchFile, cleanedTop + appendText, 'utf8')
      return true
    } catch {
      return false
    }
  }

  /** 把 patch 内容切分为"条目块"（`- id:` 及其缩进子行 + 前置注释行）。
   * 每块文本保留行尾换行，块间 join 不粘连；顶格注释单独成块（不并入前一条目，
   * 否则重写时注释会与下一条目粘连成一行、后续 `disabled: true` 等错挂条目）。 */
  function extractPatchBlocks(content: string): Array<{ id?: string; text: string }> {
    const lines = content.split('\n')
    const blocks: Array<{ id?: string; text: string }> = []
    let current: { id?: string; text: string } | null = null
    for (const line of lines) {
      const idMatch = /^\s*- id:\s*([^\s#]+)/.exec(line)
      if (idMatch) {
        if (current) blocks.push(current)
        current = { id: idMatch[1], text: line + '\n' }
      } else if (current) {
        if (/^\s/.test(line) || line.trim() === '') {
          // 条目缩进子行或空行：留在当前块
          current.text += line + '\n'
        } else {
          // 顶格注释/杂散行：结束当前块，单独成块保留（防止与下一条目粘连）
          blocks.push(current)
          current = null
          blocks.push({ text: line + '\n' })
        }
      } else if (line.trim() !== '' && !/^\s*#/.test(line) && !/^\s*\[\]\s*$/.test(line)) {
        // 非注释、非空、非条目的杂散行：保留原样（如 - insert: 包裹行）
        blocks.push({ text: line + '\n' })
      } else if (line.trim() !== '' && !/^\s*\[\]\s*$/.test(line)) {
        // 顶格注释单独成块
        blocks.push({ text: line + '\n' })
      }
    }
    if (current) blocks.push(current)
    return blocks
  }

  /**
   * ═══ 失败自愈（实测保障 + 官方路径优先）：注入器已缺席时自动重试装配
   * （3 次，间隔 4s/8s/12s）。路径选择（实测教训）：loader.create 会新建
   * **幽灵 entry**，与官方 bundles entry 并存时 loader 对账防双实例会把官方
   * entry 标 disabled——所以自愈**优先走官方装配**（touch profile patch →
   * include.refresh 重装 bundles，无幽灵）；touch 无效才 fallback
   * loader.create（保底复活）。触发方：重启器 catch（reboot-failed）与
   * 看门狗（watchdog-timeout——reboot 异步挂起时 catch 不会执行）。
   */
  function scheduleHeal(selfEntry: any, reason: string): void {
    try {
      // ⚠️ rebootCtx 用 ctx.root（loader 树根，恒活跃）：selfEntry.ctx 在自毁后
      // inactive（实测：cloud-restore 版自重载自杀后 rebuild 报 inactive context）
      const rebootCtx = ctx.root as any
      const pkgName = selfEntry?.options?.name ?? '@dsh-external/dsh-super-injector'
      const cfg = selfEntry?.options?.config ?? {}
      const patchFile = join(dirname(profileNodeModules), 'cordis.patch.yml')
      let attempt = 0
      const heal = (): void => {
        attempt += 1
        void (async () => {
          try {
            // 第一步：touch profile patch 触发官方重装配（不产生幽灵 entry）
            if (attempt <= 3) {
              try {
                mkdirSync(dirname(patchFile), { recursive: true })
                appendFileSync(patchFile, `\n# super-injector heal ${Date.now()}\n`)
                // 给 include.refresh 一个窗口，然后验证官方 entry 是否复活
                await new Promise((r) => globalThis.setTimeout(r, 3000))
                let officialAlive = false
                try {
                  for (const entry of rebootCtx.loader.entries()) {
                    const o = entry.options
                    if (o.group) continue
                    if (String(o.name).includes('dsh-super-injector') && entry.fiber && FIBER_NAMES[entry.fiber.state] === 'active') {
                      officialAlive = true
                    }
                  }
                } catch { /* 枚举失败按未复活处理 */ }
                if (officialAlive) {
                  logger.info('[super-injector] 自愈：第 %d 次 touch patch 官方重装配生效（%s）', attempt, pkgName)
                  opStats.selfHeal.ok += 1
                  saveStats()
                  auditLog('heal-ok', `第 ${attempt} 次 touch patch 官方重装配成功（${pkgName}，触发=${reason}）`)
                  // 自愈成功后仲裁：清理可能残留的幽灵 entry（fallback create 曾制造过）
                  arbitrateOfficial()
                  return
                }
                throw new Error('touch patch 后官方 entry 未复活')
              } catch (e) {
                // touch 无效 → 降级 loader.create（保底，会留幽灵 entry）
                const lc = rebootCtx.loader.internal?.loadCache as Map<string, unknown> | undefined
                if (lc && typeof lc.delete === 'function') {
                  for (const u of [...lc.keys()]) {
                    if (typeof u === 'string' && decodeURIComponent(u).includes(pkgName)) {
                      Map.prototype.delete.call(lc, u)
                    }
                  }
                }
                await rebootCtx.loader.create({ name: pkgName, config: cfg })
                logger.info('[super-injector] 自愈：第 %d 次 fallback loader.create 重新装配完成（%s）', attempt, pkgName)
                opStats.selfHeal.ok += 1
                saveStats()
                auditLog('heal-ok', `第 ${attempt} 次 fallback loader.create 重新装配成功（${pkgName}，触发=${reason}）`)
                // fallback create 会制造幽灵 entry——立即仲裁让官方 entry 接管
                arbitrateOfficial()
              }
            }
          } catch (e) {
            logger.error('[super-injector] 自愈第 %d 次失败: %s', attempt, String(e))
            opStats.selfHeal.fail += 1
            auditLog(`heal-failed`, `第 ${attempt} 次失败: ${String(e)}（触发=${reason}）`)
            if (attempt < 3) globalThis.setTimeout(heal, 4000)
            else auditLog('heal-exhausted', '3 次均失败（需人工介入：修复产物后 touch profile patch 触发重装配）')
          }
        })()
      }
      globalThis.setTimeout(heal, 4000)
      logger.warn('[super-injector] 自愈已排程（4s 后第 1 次：touch patch 官方装配，最多 3 次，触发=%s）', reason)
    } catch (e) {
      logger.error('[super-injector] 自愈排程失败: %s', String(e))
    }
  }

  async function reloadPackage(match: string, urlMatch?: string): Promise<string> {
    const internal = ctx.loader.internal
    if (!internal) return 'ERROR: loader.internal 不可用'
    const loadCache = internal.loadCache as Map<string, any>

    const urlKey = (urlMatch ?? match).replace(/\\/g, '/')
    let urls = [...loadCache.keys()].filter((u) => {
      if (typeof u !== 'string') return false
      return decodeURIComponent(u).includes(urlKey)
    })
    // ═══ P0 根治（外部测评确认）：缓存无匹配不再 INFO 退出 ═══
    // 缓存丢失场景（并行 build/自检交错 purge、进程内 loadCache 被清）会让
    // 自重载/热重载直接失效（实测多次 + 测评复现）。降级：从磁盘 URL 直接
    // import（junction 路径 / urlMatch 目录的 lib/index.js），loader.import
    // 会重新解析磁盘文件并填充缓存——重载流程继续，链路自愈。
    // ⚠️ 匹配必须用 realpath（实测踩坑）：副本目录（如 cloud-restore）不含
    // 包名——按 urlKey（包名）重新匹配会失败。realpathSync(lib) 与 loadCache
    // 的真实 key（realpath URL）一致。
    let entryUrl: string | undefined
    if (urls.length === 0) {
      let libPath: string | undefined
      try {
        const entry = findEntry(match)
        const name = entry?.options?.name
        const candidates: string[] = []
        if (name) {
          const parts = name.startsWith('@') ? name.split('/') : [name]
          candidates.push(join(profileNodeModules, ...parts, 'lib', 'index.js'))
        }
        if (urlMatch) candidates.push(join(urlMatch, 'lib', 'index.js'))
        for (const lib of candidates) {
          if (existsSync(lib)) { libPath = lib; break }
        }
        if (libPath) {
          // ⚠️ 必须 import realpath URL 而非 junction URL（实测踩坑）：tsx 按 URL
          // 缓存模块，junction 路径变化（如自检 tmpDir 迁移）后 junction URL 仍
          // 命中旧模块缓存，loadCache 不产生新 key → 匹配仍失败。realpath URL
          // 是全新 key，强制重新解析磁盘并填充缓存。
          const realLib = realpathSync(libPath)
          await ctx.loader.import(pathToFileURL(realLib).href, () => [])
          const real = realLib.replace(/\\/g, '/')
          for (const u of loadCache.keys()) {
            if (typeof u === 'string' && decodeURIComponent(u).includes(real)) { entryUrl = u; break }
          }
        }
      } catch { /* 降级失败继续走下面判断 */ }
      if (entryUrl) {
        auditLog('cache-miss-healed', `缓存无匹配已降级从磁盘加载（${urlKey} → ${entryUrl}）`)
        // ⚠️ 关键（实测踩坑）：降级路径下外层 urls 仍为空——后续预检的
        // purge（for u of urls delete）不生效 → import 命中旧模块 → 预检
        // 误通过 → 真自杀。把降级得到的 key 补进 urls，预检才能 purge 后
        // 重读磁盘（文件损坏时正确拦截）。
        urls = [entryUrl]
      }
    } else {
      entryUrl = urls.find(u => u.endsWith('/lib/index.js'))
    }
    if (!entryUrl) return `INFO: 缓存中无匹配且磁盘降级失败 "${urlKey}" 的模块`
    const entryUrlFinal = entryUrl

    // ═══ 构建产物新鲜度预检（2026-08-14 index build 事件教训）═══
    // 重载前检查目标包：lib/client.js 缺失/非 tsdown 产物 → 阻断（重载后
    // 前端必挂，client-modules rebuilt 只会把坏 bundle 广播出去）；src 比
    // 产物新（漏构建）→ audit 留痕提醒（mtime 在 git checkout 场景可能
    // 误报，故只警告不阻断）。
    try {
      const base = dirname(dirname(fileURLToPath(entryUrlFinal)))
      const fresh = buildFreshnessProblems(base)
      if (fresh.block.length > 0) {
        auditLog('reload-blocked-stale', `${urlKey}: ${fresh.block.join('; ')}`)
        return 'ERROR: 重载前构建产物预检失败（先修复再重载，否则前端必挂）：\n- ' + fresh.block.join('\n- ')
          + '\n修复：npm run build:all（host + client 两步构建）→ 再重载'
      }
      if (fresh.warn.length > 0) {
        auditLog('reload-stale-artifacts', `${urlKey}: ${fresh.warn.join('; ')}`)
        logger.warn('[super-injector] 重载 %s 构建产物可能过期（未阻断）: %s', urlKey, fresh.warn.join('; '))
      }
    } catch { /* 目录解析失败不阻断（其余预检兜底） */ }

    // ═══ 重启器（自重载专用）：自杀后脱离自身 fiber 完成重建 ═══
    // 自重载时 dispose 会把当前 fiber（含本工具）销毁，随后的重建代码
    // 跑在已销毁的上下文里必然失败。解决：先 dispose + purge（释放文件
    // 句柄，不锁定 lib 文件），再用**全局 setTimeout**（不属于任何 fiber
    // 的 disposables，dispose 不会清它）延迟重建——自杀后生命周期由全局
    // 定时器延续，直到重建结束。
    const isSelf = matchesSelf(match)
    if (isSelf) {
      // 防自毁①：窗口锁——自杀→重建期间拒绝再次自重载
      if (selfReloading) {
        return 'ERROR: 自重载窗口进行中（自杀→重建约 1-2 秒），请稍后再试——防止连环自杀'
      }
      // 防自毁②：节流（文件持久化，跨自重载实例）——最小间隔内拒绝
      const since = Date.now() - readSelfReloadState().at
      if (since < SELF_RELOAD_MIN_INTERVAL_MS) {
        return `ERROR: 自重载节流：距上次仅 ${Math.round(since / 1000)}s（最小间隔 ${SELF_RELOAD_MIN_INTERVAL_MS / 1000}s）——防止循环自杀`
      }
      selfReloading = true
      writeSelfReloadState(Date.now())
      auditLog('self-reload', `自重载触发（match=${match}），自杀并排程重启器`)
      const selfEntry = findEntry(match)

      // ═══ 稳定性增强①：预检后自杀 ═══
      // 自杀前先验证新代码可加载且导出是有效插件——文件损坏/语法错误/导出
      // 缺失在自杀前被拦截（拒绝自杀，旧代码继续跑），从源头消灭「自杀后
      // 发现代码坏」的自毁场景（之前实测踩过：lib 损坏 → 自杀 → 重建失败）。
      // ⚠️ 必须先 purge 再 import：loader.import 命中 loadCache 会返回**旧
      // 模块**（不重读磁盘）——缓存里的好代码会让预检形同虚设（实测踩坑：
      // 破坏文件后预检通过、reboot 重读才失败）。purge 后 import 读到磁盘
      // 新文件，预检才真实。
      // ⚠️ 预检失败（拒绝自杀）时必须**恢复缓存**：purge 后旧模块 job 已丢，
      // 注入器虽继续运行（fiber 在内存）但 loadCache 空 → 下次自重载报
      // 「缓存中无匹配」无法执行（实测踩坑）。
      // ⚠️ loadCache 是 Node 内部特殊 Map：写入必须 Map.prototype.set.call
      // （直接 .set() 触发内部参数校验，对 ModuleJob 抛 "type must be string"，
      // 实测踩坑）。
      const precheckBackup = new Map<string, unknown>()
      for (const u of urls) {
        precheckBackup.set(u, loadCache.get(u))
        Map.prototype.delete.call(loadCache, u)
      }
      const restorePrecheckCache = (): void => {
        for (const [u, job] of precheckBackup) {
          if (job === undefined) Map.prototype.delete.call(loadCache, u)
          else Map.prototype.set.call(loadCache, u, job)
        }
      }
      try {
        const probeNs = await ctx.loader.import(entryUrlFinal, () => [])
        const probe = ctx.loader.unwrapExports(probeNs)
        const valid = probe && (typeof probe === 'function' || typeof probe.apply === 'function')
        if (!valid) {
          restorePrecheckCache()
          selfReloading = false
          return 'ERROR: 自重载预检失败——新代码导出非有效插件（缺 apply），已拒绝自杀（旧代码继续运行）'
        }
      } catch (e) {
        restorePrecheckCache()
        selfReloading = false
        auditLog('precheck-failed', String(e))
        return `ERROR: 自重载预检失败——新代码无法加载（${String(e).slice(0, 200)}），已拒绝自杀（旧代码继续运行，缓存已恢复）`
      }

      // ═══ v0.3 最终形态：工具只排程、绝不亲自自杀 ═══
      // 实测（REPLACE 重构时）：工具在自身 fiber 上执行 dispose（自杀）会被
      // cordis 取消执行（"inactive context"）——即使 rebuild 成功工具也抛错。
      // 正解：自杀+重建全部移进 reboot（global setTimeout，独立于自身 fiber
      // 生命周期——重启器本来的设计语义）。工具这里只：purge 缓存 + 排程。
      try {
        for (const u of urls) Map.prototype.delete.call(loadCache, u)
      } catch { /* 清理失败不阻塞 */ }
      // ═══ 稳定性增强②：看门狗 ═══
      // 自杀后 5 秒检查重建是否完成；若 reboot 挂起（import 永不 resolve/
      // reject 的异步堵塞）→ catch 不会触发 → 注入器永久缺席。看门狗主动
      // 发现并触发自愈（touch patch 官方装配优先 + fallback loader.create）。
      globalThis.setTimeout(() => {
        try {
          const cur = selfEntry?.fiber
          if (!cur || FIBER_NAMES[cur.state] !== 'active') {
            auditLog('watchdog', '重启器 5s 未完成重建（疑似异步挂起），触发自愈')
            scheduleHeal(selfEntry, 'watchdog-timeout')
          }
        } catch { /* 看门狗失败静默 */ }
      }, 5000)
      // 全局定时器（globalThis.setTimeout，非 fiber 的 ctx.setTimeout）
      const planned = globalThis.setTimeout(() => {
        void (async () => {
          try {
            // ═══ v0.3 重构：官方 REPLACE 语义（SPEC §1.1/4.3，实测校准）═══
            // 与 entry.update 的 REPLACE 分支同构（entry.ts L214-246）：
            //   import 新模块（经 entry.parent.tree——与 include 装配同路径）
            //   → entry._dispose()（官方：_disposing 豁免 + entry.fiber 清空）
            //   → fiber 创建（registry.plugin）+ 手动关联 entry
            //   → 失败 rollback（官方语义）
            // ⚠️ 实测校准（entry.ctx 不可用）：reboot 上下文（global setTimeout，
            // 无活跃 fiber）里 entry.ctx 的服务解析抛 inactive（它关联注入器
            // fiber 链，自杀后失效）——fiber 创建必须走 rebootCtx（ctx.root，
            // 原型链到 loader 活跃 fiber）。代价：fiber.parent 无 Entry.key →
            // loader 监听不自动设 fiber.entry → 手动关联（nf.entry + entry.fiber）
            // 是 reboot 上下文的必要适配，且需 _disposing 豁免（entry._dispose
            // 官方计数）与 disabled 兜底清理。
            const entry = selfEntry as any
            if (!entry || typeof entry._dispose !== 'function') {
              throw new Error('selfEntry 无官方 _dispose（loader 契约缺失）')
            }
            const rebootCtx = ctx.root as any
            const previousPlugin = entry.fiber?.runtime?.callback ?? null
            const fresh = rebootCtx.loader.unwrapExports(
              await entry.parent.tree.import(entry.options.name, () => []),
            )
            await entry._dispose()
            const startWith = async (plugin: any): Promise<void> => {
              const fiber = rebootCtx.registry.plugin(plugin, entry.options.config ?? {}, entry.getOuterStack)
              fiber.entry = entry
              entry.fiber = fiber
              await fiber.await()
              // 兜底：清 disabled（新 fiber 可能触发 loader case 7 标记）
              try {
                if (entry.options.disabled !== undefined) delete entry.options.disabled
                const parent = entry.parent
                if (parent && Array.isArray(parent.data)) {
                  for (const d of parent.data) {
                    if (d && d.id === entry.id && d.disabled !== undefined) delete d.disabled
                  }
                }
              } catch { /* 清理失败不阻塞 */ }
            }
            try {
              await startWith(fresh)
            } catch (error) {
              // 官方 rollback：旧插件重新装配
              if (previousPlugin) {
                try {
                  await startWith(previousPlugin)
                } catch (rollbackError) {
                  throw new AggregateError([error, rollbackError], 'reboot 与 rollback 均失败')
                }
              }
              throw error
            }
            // ⚠️ client 表补扫（实测）：reboot 的新 fiber 经 rebootCtx.registry
            // 创建（parent 无 Entry.key）——client-modules 的 internal/plugin
            // 监听读不到 fiber.entry → 不 processOne → 注入器自身的 client
            // （settings 插件管理页）不注册。startWith 成功后显式补扫——
            // 必须走 rebootCtx（ctx.root 活跃；注入器 ctx 自杀后 inactive，
            // refreshClientRow 内部用它取 clientModules 会静默失败）。
            try {
              const name = String(entry.options.name ?? '')
              if (name) {
                const cm = rebootCtx.get('clientModules') as { processOne?: (id: string) => unknown } | undefined
                if (cm && typeof cm.processOne === 'function') cm.processOne(name)
              }
            } catch { /* client 补扫失败不阻塞 */ }
            logger.info('[super-injector] 重启器重建完成（REPLACE 语义，fiber=%s）', entry.fiber?.state)
          } catch (error) {
            logger.error('[super-injector] 重启器重建失败: %s', String(error))
            console.error('[super-injector] 重启器重建失败:', error)
            auditLog('reboot-failed', String(error))
            // 失败自愈（抽成 scheduleHeal，与看门狗共用）
            scheduleHeal(selfEntry, 'reboot-failed')
          } finally {
            // 防自毁③：无论成败都释放窗口锁（失败时注入器已缺席，锁必须
            // 释放以便后续手动/自动恢复路径可重新装配）
            selfReloading = false
          }
        })()
      }, 100)
      void planned
      return `OK: 注入器已自杀（dispose + 释放文件句柄），重建已排程（100ms 后由全局定时器执行——重启器生命周期独立于自身 fiber）`
    }

    // 防自毁④：非自重载路径（普通重载）若匹配到注入器自身 entry → 拒绝。
    // 普通路径会在 dispose 自身 fiber 后继续跑注入器 ctx 的代码（inactive
    // context 必然炸），且无重启器兜底——等于无保护的自我处决。
    for (const entry of ctx.loader.entries()) {
      const o = entry.options
      if (o.group) continue
      if (!String(o.name).includes('dsh-super-injector')) continue
      if (String(o.name).includes(match) || String(o.id).includes(match)) {
        return 'ERROR: 重载目标命中注入器自身，但未走自重载路径（匹配串需含 dsh-super-injector）。已拒绝——防止无保护自毁'
      }
    }

    const oldJob = loadCache.get(entryUrlFinal)
    // 坏 job 兜底：旧模块可能卡在 "not instantiated"（此前失败中断的残留），
    // getNamespace 会抛错把重载堵死——此时放弃回滚（坏状态无法回滚），直接
    // purge 后 import 重建。回滚备份仅在旧插件可正常解出时才有意义。
    let oldPlugin: any = null
    let oldJobUsable = false
    try {
      oldPlugin = ctx.loader.unwrapExports(oldJob?.module?.getNamespace())
      oldJobUsable = oldPlugin !== null && oldPlugin !== undefined
    } catch {
      oldJobUsable = false
    }
    if (!oldJobUsable) {
      // 清缓存 + 直接重 import（无旧代可回滚，失败则保留旧缓存原样）
      const backup = new Map<string, any>()
      for (const u of urls) {
        backup.set(u, loadCache.get(u))
        Map.prototype.delete.call(loadCache, u)
      }
      try {
        const fresh = ctx.loader.unwrapExports(await ctx.loader.import(entryUrlFinal, () => []))
        for (const entry of ctx.loader.entries()) {
          const opts = entry.options as { name?: string; id?: string }
          if (opts?.name && String(opts.name).includes(match)) {
            const fiber = entry.fiber
            if (fiber && typeof fiber === 'object') {
              // 尝试用新插件导出重建 fiber（entry 的 plugin 引用替换）
              // ⚠️ 先 await 旧 fiber dispose（异步清理防注册竞态）
              if (typeof fiber.dispose === 'function') {
                try { await fiber.dispose() } catch { /* 忽略 */ }
              }
              const registry = (ctx as any).registry
              if (registry && typeof registry.delete === 'function' && typeof registry.plugin === 'function') {
                registry.delete(fiber)
                const nf = registry.plugin(fresh, entry.options.config ?? {}, () => [])
                nf.entry = entry
                entry.fiber = nf
              }
            }
          }
        }
        return `OK: ${match} 坏缓存兜底重载完成（无旧代回滚）`
      } catch (e) {
        for (const [u, job] of backup) loadCache.set(u, job)
        return 'ERROR: 兜底 import 失败，已恢复原缓存: ' + (e instanceof Error ? e.stack : String(e))
      }
    }

    const runtime = ctx.registry.get(oldPlugin)
    // registry 无 runtime（模块实例不匹配：watch/rescue 等路径建的 fiber 与
    // oldJob namespace 不同）——不依赖 registry.get，直接 entry.fiber 重建。
    if (!runtime) {
      const target = [...ctx.loader.entries()].find((en) => {
        const o = en.options as { name?: string }
        return o?.name && String(o.name).includes(match)
      })
      if (target?.fiber) {
        try {
          if (typeof target.fiber.dispose === 'function') await target.fiber.dispose()
          const backup2 = new Map<string, any>()
          for (const u of urls) {
            backup2.set(u, loadCache.get(u))
            Map.prototype.delete.call(loadCache, u)
          }
          const fresh2 = ctx.loader.unwrapExports(await ctx.loader.import(entryUrlFinal, () => []))
          const nf2 = ctx.registry.plugin(fresh2, target.options.config ?? {}, () => [])
          nf2.entry = target
          target.fiber = nf2
          normalizeEntriesByName(match)
          return `OK: registry 无 runtime，entry.fiber 直接重建（state=${nf2.state}）`
        } catch (e) {
          return 'ERROR: entry 重建失败: ' + (e instanceof Error ? e.stack : String(e))
        }
      }
      return 'ERROR: registry 中无该插件 runtime 且 entry 无 fiber'
    }

    // 清缓存（备份以便回滚）
    const backup = new Map<string, any>()
    for (const u of urls) {
      backup.set(u, loadCache.get(u))
      Map.prototype.delete.call(loadCache, u)
    }

    // 重新 import（失败 → 恢复缓存，旧代保留）
    let fresh: any
    try {
      fresh = ctx.loader.unwrapExports(await ctx.loader.import(entryUrlFinal, () => []))
    } catch (e) {
      for (const [u, job] of backup) loadCache.set(u, job)
      return 'ERROR: import 失败，已回滚缓存（旧代保留）: ' + (e instanceof Error ? e.stack : String(e))
    }

    // 从 loader entry 重读当前装配配置（避免用陈旧 _config 覆盖 include.refresh
    // 热更新的配置——2026-08-12 蒸馏配置被固化的根因）。entry 的 config 是 patch
    // 原始配置（可能缺 schema 默认字段），与 fallback（schema 已填充的旧配置）
    // 浅合并：旧值保底、entry 新值覆盖。找不到 entry 时回退旧配置。
    function currentConfigOf(fallback: unknown): unknown {
      try {
        for (const entry of ctx.loader.entries()) {
          const opts = entry.options as { name?: string; config?: unknown }
          if (opts?.name && String(opts.name).includes(match) && opts.config !== undefined) {
            if (typeof fallback === 'object' && fallback !== null
              && typeof opts.config === 'object' && opts.config !== null) {
              return { ...(fallback as Record<string, unknown>), ...(opts.config as Record<string, unknown>) }
            }
            return opts.config
          }
        }
      } catch {
        // 读配置失败回退
      }
      return fallback
    }

    // dispose 旧 fiber + 重建（失败 → 尝试用旧插件恢复）
    // ⚠️ 快照 fiber 列表：runtime.fibers 是 DisposableList（活引用），
    // 下方 await 旧 fiber dispose 会把 fiber 从列表移除——若直接遍历活
    // 列表，重建循环看到的永远是空列表（实测「重建 0 fiber」）。快照
    // 必须在 dispose 之前完成。
    const fibers = [...runtime.fibers] as any[]
    const failures: string[] = []
    let rebuilt = 0
    try {
      const config = currentConfigOf(fibers[0]?._config)
      // ⚠️ 竞态修复：cordis 的 fiber.dispose() 是异步清理（_unload await disposables，
      // 含 context/tools 注册注销）——必须先 await 旧 fiber 完全 dispose，
      // 再建新 fiber，否则新 fiber apply 时旧注册残留 → duplicate（此前热
      // 重载连环 "already registered" 的根因）。registry.delete 是 fire-and-forget，
      // 所以这里直接 await entry.fiber 的 dispose（返回 disposalTask Promise）。
      const entryForDispose = [...ctx.loader.entries()].find((en) => {
        const o = en.options as { name?: string }
        return o?.name && String(o.name).includes(match)
      })
      const oldFiberEntry = entryForDispose?.fiber
      if (oldFiberEntry && typeof oldFiberEntry.dispose === 'function') {
        try {
          await oldFiberEntry.dispose()
        } catch { /* dispose 清理失败不阻塞重建 */ }
      }
      ctx.registry.delete(oldPlugin)
      const newFibers: any[] = []
      for (const oldFiber of fibers) {
        try {
          const fiber = oldFiber.parent.registry.plugin(fresh, config, () => [])
          fiber.entry = oldFiber.entry
          if (fiber.entry) fiber.entry.fiber = fiber
          newFibers.push(fiber)
          rebuilt++
        } catch (e) {
          failures.push(String(e))
        }
      }
      // ⚠️ 等新 fiber 完成初始化（loading → active）：registry.plugin 同步返回的
      // fiber 还是 pending/loading——若不等，随后的 client 操作（processOne 的
      // !entry.disabled 检查、activeEntry 查找）会基于不稳定状态失败（实测
      // reload 报 client ✗ 的根因：activeEntry=none → fullName 回落短名 →
      // processOne 精确匹配失败；reload 返回后 fiber 才转 active 补注册）。
      await Promise.allSettled(newFibers.map((f) => {
        const p = typeof f.await === 'function' ? f.await() : undefined
        return p ?? Promise.resolve()
      }))
    } catch (e) {
      // 整体失败：回滚缓存 + 用旧插件重建
      for (const [u, job] of backup) loadCache.set(u, job)
      try {
        ctx.registry.delete(fresh)
        for (const oldFiber of fibers) {
          const fiber = oldFiber.parent.registry.plugin(oldPlugin, currentConfigOf(oldFiber._config), () => [])
          fiber.entry = oldFiber.entry
          if (fiber.entry) fiber.entry.fiber = fiber
        }
      } catch { /* 尽力而为 */ }
      const message = String(e instanceof Error ? (e.stack ?? e.message) : e)
      // 强制登记守卫：duplicate route = 旧 fiber 存在「未登记到 ctx.effect 的裸注册」，
      // dispose 无法自动注销 → 新注册撞车。检测到即报错要求登记，并自动清理残留自愈。
      if (message.includes('duplicate') || message.includes('already registered')) {
        const cleaned = clearRoutesByMatch(match)
        return 'ERROR: 检测到未登记的裸注册（' + (e instanceof Error ? e.message : String(e))
          + '）——插件必须把资源注册挂到 ctx.effect（登记后 dispose 自动清理，热重载不再残留）。'
          + '\n已自动清理疑似残留路由：' + (cleaned.length ? cleaned.join(', ') : '（无）')
          + '\n请重载重试；若仍失败请检查插件源码中的裸注册。'
      }
      return 'ERROR: 重建失败，已回滚（旧代保留）: ' + message
    }

    if (failures.length) {
      return `WARN: ${match} 部分重建（${rebuilt}/${fibers.length}）: ${failures.join('; ')}`
    }
    // 清 disabled（幽灵 entry 隔离）：热重载后 client 模块可重新注册（UI 生效）
    normalizeEntriesByName(match)
    // ⚠️ 以下 client 操作必须用**完整包名**：client-modules 的 processOne 对
    // entry.options.name 做精确匹配（短名 ≠ '@dsh-external/...' 完整包名），
    // 传短名会静默注册失败（实测 reload 报 client ✗ 的根因——microtask flush
    // 后来用完整名补注册，但返回信息已经错了）。
    const activeEntry = [...ctx.loader.entries()].find((en) => {
      const o = en.options
      return !o.group && String(o.name).includes(match) && en.fiber && FIBER_NAMES[en.fiber.state] === 'active'
    })
    const fullName = activeEntry?.options.name ?? match
    // ═══ 临时诊断（排查 reload 后 client ✗）：写 reload-debug.log ═══
    try {
      const dbg = [
        `[${new Date().toISOString()}] reload match=${match} fullName=${fullName}`,
        `  activeEntry=${activeEntry ? activeEntry.id : 'none'} fiberState=${activeEntry?.fiber ? FIBER_NAMES[activeEntry.fiber.state] : '?'} entry.disabled=${activeEntry ? activeEntry.disabled : '?'} options.disabled=${activeEntry ? JSON.stringify(activeEntry.options.disabled) : '?'}`,
      ]
      const cmDbg = ctx.get('clientModules') as { clientPath?: (id: string) => string | undefined; table?: Map<string, unknown> } | undefined
      dbg.push(`  cm=${cmDbg ? 'yes' : 'no'} clientPath(short)=${cmDbg?.clientPath ? String(cmDbg.clientPath(match)) : '?'} clientPath(full)=${cmDbg?.clientPath ? String(cmDbg.clientPath(fullName)) : '?'}`)
      if (cmDbg?.table) {
        const keys: string[] = []
        for (const k of cmDbg.table.keys()) keys.push(String(k))
        dbg.push(`  table keys(${keys.length}): ${keys.filter((k) => k.includes('dsh-external')).join(',') || '(none)'}`)
      }
      appendFileSync(join(dshHome, 'super-injector', 'reload-debug.log'), dbg.join('\n') + '\n')
    } catch { /* 诊断失败不阻塞 */ }
    // client 模块补扫（表丢失/从未注册时自愈——web 重启后幽灵 entry 场景）
    refreshClientRow(fullName)
    // client bundle 联动：host 重载后 bundle rev 变化通知浏览器（改 UI → 免手动刷新）
    notifyClientRebuilt(fullName)
    // 自检：完整包名查表（表 key 是完整包名，完全匹配）
    const client = clientStatus(fullName)
    recordOp('reload', rebuilt > 0)
    return `OK: ${match} 热重载完成（清缓存 ${urls.length} 模块，重建 ${rebuilt} fiber）\n- ${client}`
  }

  // ============ 插件状态 ============
  /** 当前 loader 已装配插件清单（确定性信息：id/name/fiber 状态/入口）。 */
  function listPlugins(): string {
    const lines: string[] = []
    const injectedNames = new Set(readRegistry().map((e) => e.name))
    for (const entry of ctx.loader.entries()) {
      const opts = entry.options
      if (opts.group) continue
      const state = entry.fiber ? (FIBER_NAMES[entry.fiber.state] ?? `state:${entry.fiber.state}`) : 'no-fiber'
      const entryUrl = [...ctx.loader.internal!.loadCache.keys()]
        .find(u => typeof u === 'string' && u.includes(opts.id))
      // 注入插件标记 [injected]（与 bundle 装配区分，避免 hash id 难认）
      const injected = injectedNames.has(opts.name) ? ' [injected]' : ''
      lines.push(`- [${state}] ${opts.id} (${opts.name})${injected}${opts.disabled ? ' [disabled]' : ''}${entryUrl ? '\n    entry: ' + entryUrl : ''}`)
    }
    return lines.length ? lines.join('\n') : '（loader 中无已装配插件 entry）'
  }

  /** 查找匹配的 entry（id 或 name 子串）——优先活跃 entry，跳过 disposed/failed/disabled 残留。 */
  function findEntry(match: string): any {
    const candidates: any[] = []
    for (const entry of ctx.loader.entries()) {
      const opts = entry.options
      if (opts.group) continue
      if (opts.id.includes(match) || opts.name.includes(match)) candidates.push(entry)
    }
    if (candidates.length === 0) return undefined
    // 活跃优先（唯一在线实例）；无活跃时取第一个非 disposed/failed 的
    const live = candidates.find((e) => {
      const st = stateOf(e)
      return st === 'active'
    })
    if (live) return live
    return candidates.find((e) => {
      const st = stateOf(e)
      return st !== 'disposed' && st !== 'failed' && st !== 'no-fiber'
    }) ?? candidates[0]
  }

  // ============ 开发侧挂区（staging）：测试工具挂后侧，转正才进 schema ============
  // 任何工具增减都会改变 tools schema → DeepSeek 前缀缓存全灭 → 全量计费。
  // 开发/审计工具一律挂"后侧"（staging）：不进 schema、缓存零污染，经
  // dev_stage_call 测试；确认转正后 dev_stage_promote 一键挂"前侧"（正式注册，
  // 仅承受这一次缓存刷新）。execute 为 JS 代码字符串（function(args, ctx){...}），
  // 闭包可访问本插件的 ctx（webServer/loader/timer/tools/systemPrompt）——仅限可信代码。
  interface StagedTool {
    description: string
    parameters: Record<string, unknown>
    execute: (args: Record<string, unknown>, c: any) => unknown | Promise<unknown>
    /** execute 源码字符串（持久化用：自重载/重启后重新编译恢复）。 */
    source?: string
    promoted: boolean
    /** 转正注册的释放句柄（ctx.effect disposer）——demote 时注销正式工具。 */
    disposer?: () => void
  }
  const staged = new Map<string, StagedTool>()

  // ═══ staging 持久化：自重载（注入器自杀重建）会丢掉 apply 闭包里的 staged
  // map——promote 过的正式工具会随旧 fiber 注销而消失（实测 bug）。落盘到
  // staging.json，apply 启动时恢复（execute 源码重新编译 + promoted 重新注册）。
  const stagingFile = join(dirname(registryFile), 'staging.json')

  function saveStaging(): void {
    try {
      const data: Record<string, { description: string; parameters: unknown; source: string; promoted: boolean }> = {}
      for (const [name, t] of staged) {
        if (typeof t.source === 'string' && t.source !== '') {
          data[name] = { description: t.description, parameters: t.parameters, source: t.source, promoted: t.promoted }
        }
      }
      mkdirSync(dirname(stagingFile), { recursive: true })
      writeFileSync(stagingFile, JSON.stringify(data, null, 2), 'utf8')
    } catch { /* 持久化失败不阻塞 */ }
  }

  /** 恢复持久化的 staging（含 promoted 重新转正注册）。 */
  function restoreStaging(): void {
    try {
      if (!existsSync(stagingFile)) return
      const data = JSON.parse(readFileSync(stagingFile, 'utf8')) as Record<string, { description?: string; parameters?: unknown; source?: string; promoted?: boolean }>
      for (const [name, raw] of Object.entries(data)) {
        if (typeof raw.source !== 'string' || raw.source === '') continue
        if (staged.has(name)) continue
        let fn: Function
        try {
          fn = new Function('args', 'ctx', `return (${raw.source})(args, ctx)`)
        } catch {
          continue // 源码损坏：跳过该工具，不拖垮恢复
        }
        const tool: StagedTool = {
          description: String(raw.description ?? ''),
          parameters: (raw.parameters && typeof raw.parameters === 'object')
            ? raw.parameters as Record<string, unknown>
            : {},
          execute: fn as StagedTool['execute'],
          source: raw.source,
          promoted: raw.promoted === true,
        }
        staged.set(name, tool)
        // promoted 工具重新转正注册（ctx.effect：fiber dispose 自动注销）
        if (tool.promoted) {
          try {
            const dispose = ctx.effect(() => ctx.tools.register(defineTool({
              name,
              description: tool.description,
              parameters: tool.parameters as never,
              output: { schema: { type: 'string' }, render: (_x: unknown, v: unknown) => [{ type: 'text', text: String(v) }] },
              async execute(args: Record<string, unknown>) {
                return String(await tool.execute(args, ctx))
              },
            })))
            tool.disposer = () => dispose()
            logger.info('[super-injector] 已恢复转正工具 %s', name)
          } catch { /* 恢复注册失败：保持后侧，不炸 apply */ }
        }
      }
    } catch (e) {
      logger.warn('[super-injector] staging 恢复失败: %s', String(e))
    }
  }
  restoreStaging()

  safeRegister(defineTool({
    name: 'dev_stage_add',
    description: '开发侧挂：把测试/开发工具挂"后侧"（不进 tools schema、不污染缓存前缀），经 dev_stage_call 调用测试。execute 为 JS 代码字符串（function(args, ctx){...}），仅限可信代码。转正用 dev_stage_promote，丢弃用 dev_stage_demote。',
    parameters: {
      name: { type: 'string', required: true, description: '工具名（唯一）' },
      description: { type: 'string', required: true, description: '工具描述' },
      parameters: { type: 'json', description: '参数 schema（可选，留空则无参）' },
      execute: { type: 'string', required: true, description: 'JS 代码：function(args, ctx){ return ... }' },
    },
    output: { schema: { type: 'string' }, render: (_a: unknown, v: unknown) => [{ type: 'text', text: String(v) }] },
    async execute(args: any) {
      if (!args.name || !/^[a-zA-Z0-9_-]+$/.test(args.name)) return 'ERROR: name 缺失或含非法字符'
      if (staged.has(args.name)) return `ERROR: staging 已存在同名工具（${args.name}），先 dev_stage_demote 或换个名`
      let fn: Function
      try {
        fn = new Function('args', 'ctx', `return (${args.execute})(args, ctx)`)
      } catch (e) {
        return 'ERROR: execute 代码编译失败: ' + String(e)
      }
      staged.set(args.name, {
        description: String(args.description ?? ''),
        parameters: (args.parameters && typeof args.parameters === 'object') ? args.parameters : {},
        execute: fn as StagedTool['execute'],
        source: String(args.execute),
        promoted: false,
      })
      saveStaging()
      return `OK: ${args.name} 已挂后侧（staging，不进 schema，缓存零污染）。测试: dev_stage_call ${args.name} {"...":...}；转正: dev_stage_promote ${args.name}`
    },
  }))

  safeRegister(defineTool({
    name: 'dev_stage_call',
    description: '调用后侧（staging）工具测试：不进 schema、不污染缓存。args 为传给工具的 JSON 参数对象。',
    parameters: {
      name: { type: 'string', required: true, description: 'staging 工具名' },
      args: { type: 'json', description: '传给工具的 JSON 参数（可选）' },
    },
    output: { schema: { type: 'string' }, render: (_a: unknown, v: unknown) => [{ type: 'text', text: String(v) }] },
    async execute(a: any) {
      const t = staged.get(a.name)
      if (!t) return `ERROR: staging 无此工具（${a.name}）——dev_stage_list 查看`
      try {
        return String(await t.execute(a.args ?? {}, ctx))
      } catch (e) {
        return 'ERROR: ' + (e instanceof Error ? (e.stack ?? e.message) : String(e))
      }
    },
  }))

  safeRegister(defineTool({
    name: 'dev_stage_list',
    description: '列出后侧（staging）工具（含转正状态）',
    parameters: {},
    output: { schema: { type: 'string' }, render: (_a: unknown, v: unknown) => [{ type: 'text', text: String(v) }] },
    async execute() {
      if (staged.size === 0) return '（staging 空）'
      const lines = [...staged.entries()].map(([name, t]) => `- ${name} ${t.promoted ? '[已转正]' : '[后侧]'} : ${t.description.slice(0, 60)}`)
      return lines.join('\n')
    },
  }))

  safeRegister(defineTool({
    name: 'dev_stage_promote',
    description: '转正：把 staging 工具一键挂"前侧"（正式注册进 tools schema，下一次请求缓存刷新一次）。确认工具有效后使用。',
    parameters: { name: { type: 'string', required: true, description: 'staging 工具名' } },
    output: { schema: { type: 'string' }, render: (_a: unknown, v: unknown) => [{ type: 'text', text: String(v) }] },
    async execute(a: any) {
      const t = staged.get(a.name)
      if (!t) return `ERROR: staging 无此工具（${a.name}）`
      if (t.promoted) return `${a.name} 已在前侧（转正过）`
      try {
        // 注册挂 ctx.effect：拿 disposer，demote 时才能真正注销正式工具。
        const dispose = ctx.effect(() => ctx.tools.register(defineTool({
          name: a.name,
          description: t.description,
          parameters: t.parameters as never,
          output: { schema: { type: 'string' }, render: (_x: unknown, v: unknown) => [{ type: 'text', text: String(v) }] },
          async execute(args: Record<string, unknown>) {
            return String(await t.execute(args, ctx))
          },
        })))
        t.disposer = () => dispose()
      } catch (e) {
        return 'ERROR: 转正注册失败: ' + String(e)
      }
      t.promoted = true
      saveStaging()
      return `OK: ${a.name} 已转正挂前侧（进 schema）。注意：下一次请求将刷新缓存（唯一一次全灭）。`
    },
  }))

  safeRegister(defineTool({
    name: 'dev_stage_demote',
    description: '丢弃/撤回：从 staging 移除工具（若已转正则同时从正式工具集注销）。',
    parameters: { name: { type: 'string', required: true, description: 'staging 工具名' } },
    output: { schema: { type: 'string' }, render: (_a: unknown, v: unknown) => [{ type: 'text', text: String(v) }] },
    async execute(a: any) {
      const t = staged.get(a.name)
      if (!t) return `ERROR: staging 无此工具（${a.name}）`
      let unregistered = ''
      if (t.disposer) {
        try {
          t.disposer()
          unregistered = '，已从正式工具集注销'
        } catch (e) {
          unregistered = '，正式工具注销失败: ' + String(e)
        }
      }
      staged.delete(a.name)
      saveStaging()
      return `OK: ${a.name} 已从 staging 移除${unregistered}`
    },
  }))

  function stateOf(entry: any): string {
    return entry.fiber ? (FIBER_NAMES[entry.fiber.state] ?? `state:${entry.fiber.state}`) : 'no-fiber'
  }

  /** 等待 fiber 稳定（active/failed），最多 timeoutMs；返回最终状态。
   *  ⚠️ 超时不等于失败：fiber 可能仍在 loading（插件 apply 慢/异步初始化）——
   *  文案区分"真失败"（failed）与"检查超时"（功能以实际为准，可
   *  dev_plugin_status 复核）。 */
  function waitFiberStable(entry: any, timeoutMs = 3000): Promise<string> {
    return new Promise((resolve) => {
      let retried = false
      let start = Date.now()
      const check = () => {
        const st = stateOf(entry)
        if (st === 'active') { clearInterval(iv); resolve(st); return }
        if (st === 'failed') { clearInterval(iv); resolve(st + '（失败）'); return }
        if (Date.now() - start > timeoutMs) {
          clearInterval(iv)
          // 超时但非 failed：多数是 loading 未转完（apply 异步）——
          // 再给 2 秒重试一次，仍不稳定则如实标注"检查超时（功能以实际为准）"
          if (retried) { resolve(st + '（检查超时，功能以实际为准）'); return }
          retried = true
          start = Date.now()
          return
        }
      }
      const iv = setInterval(check, 50)
      check()
    })
  }

  // ============ 注入器核心 ============
  /**
   * 清除 loader 对账标记的 disabled（幽灵 entry 隔离）：
   * 运行时 create 的 entry 不在配置树里，loader 对账（include.refresh /
   * config 变更监听）会把它标 disabled 防双实例——而 client-modules 的
   * processOne 要求 !entry.disabled 才注册 client 模块（**注入插件的 UI
   * 不生效的根因**）。注入器语义：注入 = 完整生效（host 工具 + client UI），
   * 因此注入/重载后立即清除 disabled，让 client 模块可注册。
   * 对账只在 config 变更时触发，清除后不再次对账不会复发。
   */
  function normalizeEntry(entry: any): void {
    if (!entry) return
    try {
      const o = entry.options
      if (o && o.disabled !== undefined && o.disabled !== null) {
        delete o.disabled
        // 同步所属 group 的 data（loader 对账读取的是 group.data）
        const parent = entry.parent
        if (parent && Array.isArray(parent.data)) {
          for (const d of parent.data) {
            if (d && d.id === entry.id && d.disabled !== undefined) delete d.disabled
          }
        }
      }
    } catch { /* 清理失败不阻塞 */ }
  }

  /** 按包名清除所有同名 entry 的 disabled（注入/重载后统一调用）。 */
  function normalizeEntriesByName(name: string): void {
    for (const entry of ctx.loader.entries()) {
      const o = entry.options
      if (o.group) continue
      if (o.name === name || o.name.includes(name)) normalizeEntry(entry)
    }
  }

  /**
   * 清理同名残留 entry（disposed/failed 且无活跃 fiber），防堆积：
   * 注入失败/自杀失败的旧 entry 会留在 loader 树里，重载时 findEntry
   * 虽已活跃优先，但残留多了会让状态列表失真、`waitFiberStable` 轮询错位。
   */
  function cleanupStaleEntries(name: string): void {
    for (const entry of ctx.loader.entries()) {
      const o = entry.options
      if (o.group) continue
      if (o.name !== name) continue
      const st = entry.fiber ? FIBER_NAMES[entry.fiber.state] : 'no-fiber'
      if (st === 'active') continue
      try {
        const p = entry.parent.remove(entry.id, true)
        if (p && typeof p.then === 'function') p.catch(() => { /* 忽略 */ })
        logger.info('[super-injector] 清理残留 entry %s（%s）', entry.id, st)
      } catch { /* 清理失败不阻塞 */ }
    }
  }

  /**
   * client-modules 增量补扫：normalize disabled 发生在 loader.create 的
   * microtask flush **之后**（create await 期间 flush 已用旧 disabled 拒绝），
   * 必须主动重跑 processOne 让注入插件的 client 模块（UI）注册成功。
   * 直接调 private 方法（TS private 编译后是普通属性，运行时可见）。
   */
  function refreshClientRow(name: string): void {
    try {
      const cm = ctx.get('clientModules') as {
        processOne?: (entryName: string) => boolean
        compose?: () => unknown
        composed?: unknown
        notifyGraphChanged?: () => void
      } | undefined
      if (!cm || typeof cm.processOne !== 'function') return
      const changed = cm.processOne(name)
      if (changed && typeof cm.compose === 'function' && typeof cm.notifyGraphChanged === 'function') {
        cm.composed = cm.compose()
        cm.notifyGraphChanged()
        logger.info('[super-injector] client 模块已注册 %s', name)
      }
    } catch (e) {
      logger.warn('[super-injector] client 模块补扫失败: %s', String(e))
    }
  }

  /**
   * 通知 client-modules 重哈希 bundle（rebuilt 是 HMR watch 注册钩子）：
   * host 热重载后 client bundle rev 变化 → onGraphChanged → 浏览器端
   * HMR/刷新拉新 bundle——改 UI 代码 → build:client → reload → 免手动刷新。
   */
  function notifyClientRebuilt(name: string): void {
    try {
      const cm = ctx.get('clientModules') as { rebuilt?: (id: string) => string | undefined } | undefined
      if (cm && typeof cm.rebuilt === 'function') {
        const rev = cm.rebuilt(name)
        if (rev) logger.info('[super-injector] client bundle 已联动（rev=%s）', rev)
      }
    } catch { /* client 联动失败不阻塞 */ }
  }

  /** 卸载后从 client 模块表移除行（client-modules 只订阅 internal/plugin 增事件，卸载不自动清）。 */
  function removeClientRow(name: string): void {
    try {
      const cm = ctx.get('clientModules') as {
        table?: Map<string, unknown>
        compose?: () => unknown
        composed?: unknown
        notifyGraphChanged?: () => void
      } | undefined
      if (!cm || !cm.table) return
      if (cm.table.delete(name)) {
        if (typeof cm.compose === 'function' && typeof cm.notifyGraphChanged === 'function') {
          cm.composed = cm.compose()
          cm.notifyGraphChanged()
        }
        logger.info('[super-injector] client 模块表已移除 %s', name)
      }
    } catch { /* 清理失败不阻塞 */ }
  }

  // ═══ 操作自检与统计：每次注入/重载/卸载/安装后验证 client 模块状态并
  // 记账——操作结果可验证（host ✓ / client ✓），成功率可追溯（准确率）。
  // ⚠️ 统计持久化 stats.json（跨重启累计）：自重载会重建 fiber（内存清零），
  // 落盘后历史可追溯——dev_plugin_status 显示的是累计口径。
  const statsFile = join(dirname(registryFile), 'stats.json')

  interface OpStat { ok: number; fail: number }
  interface FailRecord { kind: string; at: string; reason: string }
  interface OpStatsMap {
    inject: OpStat
    reload: OpStat
    uninject: OpStat
    install: OpStat
    selfHeal: OpStat
    lastFailures: FailRecord[]
  }
  const EMPTY_STATS: OpStatsMap = {
    inject: { ok: 0, fail: 0 },
    reload: { ok: 0, fail: 0 },
    uninject: { ok: 0, fail: 0 },
    install: { ok: 0, fail: 0 },
    selfHeal: { ok: 0, fail: 0 },
    lastFailures: [],
  }

  function loadStats(): OpStatsMap {
    try {
      const raw = JSON.parse(readFileSync(statsFile, 'utf8')) as OpStatsMap
      const num = (v: unknown): number => (typeof v === 'number' ? v : 0)
      const fails = Array.isArray(raw?.lastFailures) ? raw.lastFailures.slice(-5) : []
      return {
        inject: { ok: num(raw?.inject?.ok), fail: num(raw?.inject?.fail) },
        reload: { ok: num(raw?.reload?.ok), fail: num(raw?.reload?.fail) },
        uninject: { ok: num(raw?.uninject?.ok), fail: num(raw?.uninject?.fail) },
        install: { ok: num(raw?.install?.ok), fail: num(raw?.install?.fail) },
        selfHeal: { ok: num(raw?.selfHeal?.ok), fail: num(raw?.selfHeal?.fail) },
        lastFailures: fails,
      }
    } catch {
      return { ...EMPTY_STATS, inject: { ...EMPTY_STATS.inject }, reload: { ...EMPTY_STATS.reload }, uninject: { ...EMPTY_STATS.uninject }, install: { ...EMPTY_STATS.install }, selfHeal: { ...EMPTY_STATS.selfHeal }, lastFailures: [] }
    }
  }

  const opStats: OpStatsMap = loadStats()

  function saveStats(): void {
    try {
      mkdirSync(dirname(statsFile), { recursive: true })
      writeFileSync(statsFile, JSON.stringify(opStats, null, 2), 'utf8')
    } catch { /* 统计写失败不阻塞 */ }
  }

  /** 审计摘要：最近 3 条故障/自愈事件（读 self-heal.log 尾部）。 */
  function auditSummary(): string {
    try {
      if (!existsSync(selfHealLogFile)) return ''
      const lines = readFileSync(selfHealLogFile, 'utf8').trim().split('\n').filter(Boolean)
      if (lines.length === 0) return ''
      return '\n===== 故障审计（self-heal.log 尾部 3 条）=====\n' + lines.slice(-3).join('\n')
    } catch {
      return ''
    }
  }

  /** 验证 client 模块注册状态（host 侧已完成后的第二验证面）。
   * 区分「无 client 声明（预期跳过）」与「有声明但注册失败（真 ✗）」。 */
  function clientStatus(name: string): string {
    // 1. 读包 package.json 判断是否有 client 声明（从 junction 路径）
    let declared = false
    try {
      const parts = name.startsWith('@') ? name.split('/') : [name]
      const pkgFile = join(profileNodeModules, ...parts, 'package.json')
      const pkg = JSON.parse(readFileSync(pkgFile, 'utf8')) as { dsh?: { client?: { platform?: string } } }
      declared = !!(pkg.dsh?.client && pkg.dsh.client.platform === 'web')
    } catch { /* 读不到按无声明处理 */ }
    if (!declared) return 'client 跳过（无 client 声明，属预期）'
    // 2. 有声明 → 查注册表
    try {
      const cm = ctx.get('clientModules') as {
        clientPath?: (id: string) => string | undefined
        table?: Map<string, unknown>
      } | undefined
      if (!cm || typeof cm.clientPath !== 'function') return 'client 服务不可用'
      let path = cm.clientPath(name)
      if (!path && cm.table && typeof cm.table.keys === 'function') {
        // match 可能是短名，client 表 key 是完整包名
        // （'@dsh-external/<name>'）——按子串宽松匹配避免误报。
        for (const key of cm.table.keys()) {
          if (String(key).includes(name)) {
            path = cm.clientPath(key)
            break
          }
        }
      }
      return path ? `client ✓ (${path.split(/[\\/]/).slice(-2).join('/')})` : `client ✗（已声明 client 但注册失败——检查 client bundle 是否构建（build:client）与 entry 状态）`
    } catch {
      return 'client 状态未知'
    }
  }

  type OpKind = 'inject' | 'reload' | 'uninject' | 'install' | 'selfHeal'

  /** 记录一次操作结果（ok=true 记成功，否则记失败 + 失败原因可审计）；落盘跨重启累计。 */
  function recordOp(kind: OpKind, ok: boolean, reason?: string): void {
    const bucket = opStats[kind]
    if (ok) bucket.ok += 1
    else {
      bucket.fail += 1
      opStats.lastFailures = [...opStats.lastFailures.slice(-4), { kind, at: new Date().toISOString(), reason: reason ?? '' }]
    }
    saveStats()
  }

  /**
   * B: 官方 entry 仲裁——幽灵压制官方时自动清理恢复（kill_zombie 自动化）。
   * 场景（实测多次踩坑）：运行时 loader.create（注入/自愈 fallback）产生幽灵
   * entry，与官方 bundles entry 并存 → include 对账把官方 entry 标 disabled →
   * 官方清单 enabled=false、实际跑在幽灵上。仲裁：检测到「官方 disabled +
   * 幽灵 active」→ 排程（1s 后，避开当前调用栈）：dispose 幽灵 → 移除幽灵
   * entry → 恢复官方（清 disabled + refresh）。触发点：apply 末尾 + 自愈成功。
   */
  function arbitrateOfficial(): void {
    try {
      const entries = [...ctx.loader.entries()].filter((e) => !e.options.group && String(e.options.name).includes('dsh-super-injector'))
      if (entries.length < 2) return
      const official = entries.find((e) => String(e.id).includes('include:'))
      const ghosts = entries.filter((e) => e !== official && e.fiber && FIBER_NAMES[e.fiber.state] === 'active')
      if (!official || !official.disabled || ghosts.length === 0) return
      auditLog('arbitrate', `幽灵压制官方（official=${official.id} disabled，ghosts=${ghosts.map((g) => g.id).join(',')}），排程清理`)
      const ghostRef = ghosts[0]
      const officialRef = official
      globalThis.setTimeout(() => {
        void (async () => {
          try {
            // 1. dispose 幽灵（当前运行实例=自杀；effect 已修，残留自动注销）
            if (ghostRef.fiber && typeof ghostRef.fiber.dispose === 'function') {
              await ghostRef.fiber.dispose()
            }
            // 2. 移除幽灵 entry
            try { await ghostRef.parent.remove(ghostRef.id, true) } catch { /* 移除失败不阻塞 */ }
            // 3. 恢复官方（清 disabled + 清 disposed fiber + refresh）
            try {
              if (officialRef.options.disabled !== undefined) delete officialRef.options.disabled
              const parent = officialRef.parent
              if (parent && Array.isArray(parent.data)) {
                for (const d of parent.data) {
                  if (d && d.id === officialRef.id && d.disabled !== undefined) delete d.disabled
                }
              }
              officialRef.fiber = undefined
              if (typeof officialRef.refresh === 'function') await officialRef.refresh()
              auditLog('arbitrate-ok', `官方 entry 恢复（${officialRef.id}），幽灵 ${ghostRef.id} 已清理`)
            } catch (e) {
              auditLog('arbitrate-failed', `官方恢复失败: ${String(e)}`)
            }
          } catch (e) {
            auditLog('arbitrate-failed', String(e))
          }
        })()
      }, 1000)
    } catch { /* 仲裁失败不阻塞 */ }
  }

  /** 注入一个本地插件包：junction → loader.create → 记录清单。 */
  async function inject(dir: string): Promise<string> {
    const absDir = resolve(dir)
    const pkgPath = join(absDir, 'package.json')
    if (!existsSync(absDir) || !statSync(absDir).isDirectory()) return `ERROR: 目录不存在或不可访问: ${absDir}`
    if (!existsSync(pkgPath)) return `ERROR: ${absDir} 存在但没有 package.json（不是插件包目录）`
    let pkg: { name?: string }
    try {
      pkg = JSON.parse(readFileSync(pkgPath, 'utf8'))
    } catch (e) {
      return 'ERROR: package.json 解析失败: ' + String(e)
    }
    const pkgName = pkg.name
    if (!pkgName) return 'ERROR: package.json 缺 name'

    // 清理同名残留 entry（disposed/failed），防止堆积与重载错位
    cleanupStaleEntries(pkgName)

    if (hasActiveEntry(pkgName)) return `INFO: ${pkgName} 已激活运行，跳过注入`
    purgeCache(absDir)

    // junction 链接到 profile node_modules（scoped 包需要两级目录）
    // ⚠️ 悬空 junction 必须重建（实测踩坑）：目标目录被删后 existsSync 返回
    // **false**（跟随链接检查目标）——判断链接存在必须用 lstatSync（链接本身
    // 还在）。悬空链接复用 → import ENOENT / symlink EEXIST。
    const scoped = pkgName.startsWith('@')
    const parts = scoped ? pkgName.split('/') : [pkgName]
    const linkDir = join(profileNodeModules, ...parts)
    try {
      let linkExists = false
      try { linkExists = lstatSync(linkDir).isSymbolicLink() || lstatSync(linkDir).isDirectory() } catch { /* 不存在 */ }
      if (!linkExists || !isHealthyLink(linkDir)) {
        if (linkExists) {
          try { rmSync(linkDir, { recursive: true, force: true }) } catch { /* 删除失败尝试覆盖 */ }
        }
        mkdirSync(dirname(linkDir), { recursive: true })
        symlinkSync(absDir, linkDir, 'junction')
      }
    } catch (e) {
      return `ERROR: 建立 junction 失败（${linkDir}）: ${String(e)}`
    }

    // 运行时装配
    try {
      await ctx.loader.create({ name: pkgName, config: {} })
    } catch (e) {
      return `ERROR: loader.create 失败: ${e instanceof Error ? e.stack : String(e)}`
    }
    // 清 disabled（幽灵 entry 隔离）：注入即完整生效（host + client UI）
    normalizeEntriesByName(pkgName)
    // client 模块补扫（loader.create 的 microtask flush 在 normalize 前已跑）
    refreshClientRow(pkgName)

    const list = readRegistry()
    if (!list.some(e => e.dir === absDir)) {
      list.push({ dir: absDir, name: pkgName, at: new Date().toISOString() })
      writeRegistry(list)
    }
    const hostOk = hasActiveEntry(pkgName)
    const client = clientStatus(pkgName)
    recordOp('inject', hostOk)
    return `OK: ${pkgName} 已注入（junction=${linkDir}）\n- host ${hostOk ? '✓' : '✗'}\n- ${client}`
  }

  /** 卸载一个已注入的插件包：卸 entry（fiber dispose）→ 清 registry → 删 junction。 */
  async function uninject(match: string, allowSelf = false): Promise<string> {
    // 自举卸载（allowSelf）：卸运行时 entry，保留 registry/junction/bundles 装配链，重启自动装回。
    if (match.includes('super-injector') && !allowSelf) return 'ERROR: 拒绝卸载 dsh-super-injector 自身（引导器不可卸载；自举卸载需 self=true）'
    const steps: string[] = []
    let fullName: string | null = null
    // 1. loader entry 卸载（同时捕获完整包名）
    for (const entry of ctx.loader.entries()) {
      const opts = entry.options
      if (opts.group) continue
      if (!opts.name.includes(match)) continue
      fullName = opts.name
      try {
        await entry.parent.remove(entry.id, true)
        steps.push('entry 已卸载: ' + opts.name)
      } catch (e) {
        steps.push('entry 卸载失败: ' + String(e))
      }
    }
    if (!steps.some(s => s.startsWith('entry 已卸载'))) steps.push('（无匹配 entry）')
    // 1.5 阻断 bundle patch 自装配：插件自带 cordis.patch.yml 会 insert 自己，
    // include.refresh 会把刚卸的 entry 加回（卸载不全的根因）。在 profile patch
    // 写 disabled 覆盖（loader patch 同 id 的 disabled 优先于 bundle 层 insert）。
    // ⚠️ 必须解析式追加（实测踩坑）：官方 patch 文件初始是顶层 `[]`（空数组），
    // 若盲 append `- id:` 会产生**两个顶层 YAML 值** → 解析必炸。正确做法：
    // 移除顶层 `[]` 空数组后再追加条目，保证文件始终是单一顶层值（列表）。
    if (fullName && !allowSelf) {
      const idShort = fullName.split('/').pop()
      if (idShort) {
        // ⚠️ 幂等：已存在同名 disabled 条目则跳过（否则重复卸载会累积条目——
        // 实测踩坑：自检多次卸载累积 6 个 self-test-plugin disabled）
        const patchFile = join(dirname(profileNodeModules), 'cordis.patch.yml')
        let already = false
        try { already = readFileSync(patchFile, 'utf8').includes(`id: ${idShort}`) } catch { /* 文件不存在 */ }
        if (already) {
          steps.push('profile patch 已有 disabled（幂等跳过）')
        } else if (writePatch(`\n# 已卸载插件（${fullName}）：disabled 阻断其 bundle patch 自装配\n- id: ${idShort}\n  disabled: true\n`)) {
          steps.push('profile patch 已写 disabled（阻断自装配，防 refresh 加回；writePatch 兼容 [] 初始形式）')
        } else {
          steps.push('profile patch 写入失败')
        }
      }
    }
    // 2. registry 清理（按 name 或目录匹配）
    const reg = readRegistry()
    const hit = reg.find(e => e.name.includes(match) || e.dir.includes(match))
    if (hit) fullName ??= hit.name
    const after = reg.filter(e => !e.name.includes(match) && !e.dir.includes(match))
    if (after.length !== reg.length) {
      writeRegistry(after)
      steps.push('registry 已清理')
    }
    // 3. junction 删除（用完整包名构建路径；rmdir 只删链接不删目标）
    if (fullName && !allowSelf) {
      const parts = fullName.startsWith('@') ? fullName.split('/') : [fullName]
      const linkDir = join(profileNodeModules, ...parts)
      try {
        if (existsSync(linkDir)) {
          rmdirSync(linkDir)
          steps.push('junction 已删除: ' + linkDir)
        } else {
          steps.push('（junction 不存在）')
        }
      } catch (e) {
        steps.push('junction 删除失败: ' + String(e))
      }
    } else {
      steps.push('（未找到完整包名，跳过 junction 清理）')
    }
    // 4. client 模块表移除（client-modules 只订阅 internal/plugin 增事件，卸载不自动清）
    if (fullName) {
      removeClientRow(fullName)
      steps.push('client 模块表已清理')
    }
    // ⚠️ 统计口径（压测发现②）：「无匹配 entry」= no-op 幂等跳过——既不计
    // ✓ 也不计 ✗（避免高估成功；真失败仍计 ✗）。此前记 fail 产生 9✗ 假失败。
    const entryUnloaded = steps.some(s => s.startsWith('entry 已卸载'))
    const noMatch = steps.some(s => s.startsWith('（无匹配 entry）'))
    if (entryUnloaded) recordOp('uninject', true)
    else if (!noMatch) recordOp('uninject', false)
    return 'OK: 卸载完成\n- ' + steps.join('\n- ')
  }

  /** junction 健康检查：能读目录 = 目标可达（Windows 断电后悬空 junction 的 lstat 仍是链接但读目录抛错）。
   *  ⚠️ 真实（非链接）目录/文件视为健康——它们是 profile 包管理器（pnpm hoisted 布局）管理的
   *  安装实体，绝不能被当成"不健康链接"删除重建（2026-08 事故：dsh-better-sidebar 经
   *  pnpm 装进 profile 后 dev_inject_plugin 把整个包目录 rmSync 掉换成了自指 junction）。 */
  function isHealthyLink(p: string): boolean {
    try {
      const st = lstatSync(p)
      if (!st.isSymbolicLink()) return true
      readdirSync(p)
      return true
    } catch {
      return false
    }
  }

  /** 启动自动恢复：① bundle junction 断电自愈（profile packages 的 link:）→ ② 注入清单逐个重新注入。 */
  /** client 骨架校验（注入前 + autoRestore 恢复前共用——pixel-forge 事件教训：
   * 坏 client 插件在 registry → 新会话恢复 → apply 失败 → HARNESS 启动失败）。
   * 返回问题列表（空 = 健康）。lib 与 src 双检查（只有 lib 无 src 不绕过）。
   * ⚠️ slot 白名单（2026-08-14 dsh-external-plugins 事件教训）：注册的 slot 名
   * 必须位于已知合法集合内——早期只认 conversation.view，导致 settings.plugin.item
   * 等设置页卡片被误判为坏骨架；同时白名单外的陌生 slot 名仍视为异常，防 typo。 */
  const KNOWN_SLOTS = ['conversation.view', 'settings.plugin.item', 'settings.plugins.tab', 'settings.section', 'settings.general.item', 'conversation.session.header.actions', 'conversation.session.header.utilities', 'conversation.input.dock', 'conversation.composer.dock', 'sidebar.footer.action', 'shell.overlay']
  const SLOT_ALT = KNOWN_SLOTS.map((s) => s.replace(/\./g, '\\.')).join('|')
  const REGISTER_NAME = new RegExp(`register\\(\\{[\\s\\S]*?name:\\s*['"](${SLOT_ALT})['"]`)

  function clientSkeletonProblems(base: string): string[] {
    const problems: string[] = []
    try {
      // 1. 编译产物（实际运行文件）——lib/client.js（CJS bundle）
      // ⚠️ 正则兼容单双引号（实测：用户手修用 "slots" 双引号——只认单引号会误判健康插件）
      const libClient = join(base, 'lib', 'client.js')
      if (existsSync(libClient)) {
        const lib = readFileSync(libClient, 'utf8')
        if (!/inject\s*=\s*\[[^\]]*['"]slots['"]/.test(lib) && !/inject\s*:\s*\[[^\]]*['"]slots['"]/.test(lib)) {
          problems.push('lib/client.js 缺 inject 含 slots（apply 用 ctx.slots 必须声明——cordis 服务注入契约）')
        }
        if (!REGISTER_NAME.test(lib)) {
          problems.push(`lib/client.js 的 register 缺合法 name（应为已知 slot：${KNOWN_SLOTS.join(' / ')}）`)
        }
      }
      // 2. 源码骨架（有 src 时）
      const clientSrcPath = join(base, 'src', 'client', 'index.ts')
      if (existsSync(clientSrcPath)) {
        const src = readFileSync(clientSrcPath, 'utf8')
        if (!/export const inject\s*=\s*\[[^\]]*['"]slots['"]/.test(src)) {
          problems.push("src/client/index.ts 缺 export const inject = ['slots']（apply 用 ctx.slots 必须声明，否则报 cannot get property 'slots' without inject）")
        }
        if (!REGISTER_NAME.test(src)) {
          problems.push(`slots.register 缺合法 name（应为已知 slot：${KNOWN_SLOTS.join(' / ')}——缺了报 slot undefined is not declared）`)
        }
      }
    } catch { /* 读不到文件时跳过 */ }
    return problems
  }

  /**
   * 构建产物新鲜度校验（2026-08-14 index build 事件教训：漏构建 client /
   * lib 过期 → 前端 bundle script failed to load + host 跑旧代码）。
   * 注入/重载/恢复/构建后四路共用：
   *  - block：必崩项——声明了 dsh.client 但 lib/client.js 缺失，或非 tsdown
   *    产物（缺 __ModuleLoader__ 特征，可能被 tsc 覆盖/手改）→ 阻断操作；
   *  - warn：质量项——src 比产物新（疑似漏 build / build:client）→ 提示。
   *    纯 mtime 比较在 git checkout 场景可能误报（检出的 src 时间戳更新），
   *    故只警告不阻断。无 src 的目录（纯 dist 发布形态）跳过新鲜度。
   */
  function buildFreshnessProblems(base: string): { block: string[]; warn: string[] } {
    const block: string[] = []
    const warn: string[] = []
    try {
      const pkgPath = join(base, 'package.json')
      if (!existsSync(pkgPath)) return { block, warn }
      // ⚠️ UTF-8 BOM 检查（2026-08-14 v0.1.2 事故教训）：PowerShell 的
      // Set-Content -Encoding UTF8 会写 BOM——package.json 带 BOM 会让
      // tsdown/JSON.parse 直接失败（client 构建不出来），而产物检查查
      // 不到（旧产物还在，特征正常）。BOM 在 package.json 里永远是错的。
      const pkgBuf = readFileSync(pkgPath)
      if (pkgBuf.length >= 3 && pkgBuf[0] === 0xEF && pkgBuf[1] === 0xBB && pkgBuf[2] === 0xBF) {
        block.push('package.json 带 UTF-8 BOM（EF BB BF）——tsdown/JSON.parse 无法解析，构建必挂；用无 BOM 工具重写（node 写文件，勿用 PowerShell Set-Content -Encoding UTF8）')
      }
      const pkg = JSON.parse(readFileSync(pkgPath, 'utf8')) as Record<string, unknown>
      const hasClient = !!(pkg.dsh as Record<string, unknown> | undefined)?.client
      // src 最新 mtime（host 与 client 分开算，避免只改 host 误报 client 过期）
      const srcDir = join(base, 'src')
      let hostLatest = 0
      let clientLatest = 0
      const walk = (dir: string, onFile: (p: string) => void): void => {
        let entries: import('node:fs').Dirent[]
        try { entries = readdirSync(dir, { withFileTypes: true }) } catch { return }
        for (const f of entries) {
          const p = join(dir, f.name)
          if (f.isDirectory()) walk(p, onFile)
          else if (/\.(ts|tsx)$/.test(f.name)) onFile(p)
        }
      }
      if (existsSync(srcDir)) {
        walk(srcDir, (p) => {
          try {
            const mt = statSync(p).mtimeMs
            const norm = p.replace(/\\/g, '/')
            if (norm.includes('/client/')) {
              if (mt > clientLatest) clientLatest = mt
            } else if (mt > hostLatest) hostLatest = mt
          } catch { /* 单文件读不到跳过 */ }
        })
      }
      // host 产物
      const libIndex = join(base, 'lib', 'index.js')
      if (existsSync(libIndex)) {
        let mt = 0
        try { mt = statSync(libIndex).mtimeMs } catch { /* 跳过 */ }
        if (hostLatest > 0 && hostLatest - mt > 8000) {
          warn.push('lib/index.js 过期（src 修改晚于构建 8s+，疑似漏 npm run build——重载会跑旧代码）')
        }
      }
      // client 产物
      if (hasClient) {
        const libClient = join(base, 'lib', 'client.js')
        if (!existsSync(libClient)) {
          block.push('lib/client.js 不存在（package.json 声明了 dsh.client 但没构建 client——先 npm run build:client，否则前端必挂）')
        } else {
          try {
            const content = readFileSync(libClient, 'utf8')
            if (!content.includes('__ModuleLoader__')) {
              block.push('lib/client.js 不是 tsdown bundle（缺 __ModuleLoader__ 特征——可能被 tsc 覆盖或手改，重新 npm run build:client）')
            }
            let mt = 0
            try { mt = statSync(libClient).mtimeMs } catch { /* 跳过 */ }
            if (clientLatest > 0 && clientLatest - mt > 8000) {
              warn.push('lib/client.js 过期（src/client 修改晚于构建 8s+，疑似漏 npm run build:client——前端会加载旧 UI）')
            }
          } catch { /* 读不到跳过 */ }
        }
      }
    } catch { /* 读不到按健康处理 */ }
    return { block, warn }
  }

  /**
   * profile link: 依赖 junction 自愈（2026-08-14 扩展）。
   *
   * 正规语义：profile package.json 的 `link:` 依赖声明 → node_modules junction
   * 物化。此前只对 `dsh.profile.bundles` 列表自愈；agent preset 行解析同样走
   * node_modules（preset 挂载 `@dsh-external/dsh-music-forge` 等本地包时按
   * ctx.baseUrl 解析）——deps 里 link: 声明但不在 bundles 的包（如
   * dsh-music-forge 供 music-producer 预设）重启后 junction 会丢，预设挂载
   * 失败。同一物化机制，同一重建逻辑，自愈范围推广到**全部 link: 依赖**。
   * registry 包（非 link:）不在此列——它们的 node_modules 由包管理器管理。
   * @returns 重建的 junction 描述列表（空 = 全部健康）。
   */
  function healProfileLinks(): string[] {
    const healed: string[] = []
    try {
      // ⚠️ 必须用带 fallback 的局部常量 profileNodeModules（config 值为空串时
      // dirname('') 解析到错误目录——曾致自愈扫描静默失败）
      const profileDir = dirname(profileNodeModules)
      const profilePkg = JSON.parse(readFileSync(join(profileDir, 'package.json'), 'utf8'))
      const bundles: string[] = profilePkg?.dsh?.profile?.bundles ?? []
      const deps: Record<string, string> = profilePkg?.dependencies ?? {}
      const bundleSet = new Set(bundles)
      const linkNames = Object.keys(deps).filter((n) => String(deps[n] ?? '').startsWith('link:'))
      for (const name of linkNames) {
        const target = String(deps[name]).slice(5)
        if (!target || !existsSync(target)) continue // 目标不存在（旧机器路径）跳过
        const scope = name.startsWith('@') ? name.split('/')[0] : null
        const linkDir = join(profileNodeModules, scope ?? '')
        const linkPath = join(linkDir, scope ? name.split('/')[1] as string : name)
        if (!isHealthyLink(linkPath)) {
          try {
            if (existsSync(linkPath)) rmdirSync(linkPath)
          } catch { /* 坏链接删除失败忽略 */ }
          try {
            mkdirSync(linkDir, { recursive: true })
            symlinkSync(target, linkPath, 'junction')
            healed.push(`${name} → ${target}`)
            logger.warn('[super-injector] 断电自愈：重建 junction %s → %s', name, target)
          } catch (err) {
            logger.warn('[super-injector] junction 重建失败 %s: %s', name, String(err))
          }
        }
      }
      // bundles 内 registry 包的悬空警告（保持原行为）
      for (const name of bundles) {
        if (bundleSet.has(name) && !linkNames.includes(name)) {
          const dep = deps[name] ?? ''
          if (!dep.startsWith('link:') && !isHealthyLink(join(profileNodeModules, ...(name.startsWith('@') ? name.split('/') : [name])))) {
            logger.warn('[super-injector] bundle %s 非 link 依赖且 junction 异常（registry 包由包管理器管理）', name)
          }
        }
      }
    } catch (err) {
      logger.warn('[super-injector] link 依赖 junction 自愈扫描失败: %s', String(err))
    }
    return healed
  }

  async function restore(): Promise<void> {    // ① profile link 依赖 junction 自愈（断电/强制关机后 junction 悬空 → 重建；
    //    覆盖 bundles 装配依赖 + agent preset 解析依赖，见 healProfileLinks）。
    try {
      healProfileLinks()
    } catch (err) {
      logger.warn('[super-injector] junction 自愈扫描失败: %s', String(err))
    }
    // ② 注入清单恢复（原逻辑）
    for (const e of readRegistry()) {
      try {
        if (hasActiveEntry(e.name)) continue
        // ⚠️ 恢复前 client 骨架校验（pixel-forge 事件教训：坏 client 插件
        // 恢复 → apply 失败 → 整个 HARNESS 启动失败——用户被迫手动修）。
        // 有问题的插件跳过恢复 + 审计（保留 registry——修复后下次启动恢复）。
        // 2026-08-14 追加：构建产物新鲜度 block 项同样跳过（漏构建 client 的
        // 插件恢复 = 前端必挂）。
        const problems = clientSkeletonProblems(e.dir)
        const fresh = buildFreshnessProblems(e.dir)
        const block = [...problems, ...fresh.block]
        if (block.length > 0) {
          auditLog('restore-skip-bad-client', `${e.name} client 骨架/构建产物问题，跳过恢复: ${block.join('; ')}`)
          logger.warn('[super-injector] 恢复 %s 跳过（client 骨架/构建产物问题）: %s', e.name, block.join('; '))
          continue
        }
        await inject(e.dir)
        logger.info('[super-injector] 自动恢复 %s', e.name)
      } catch (err) {
        logger.warn('[super-injector] 恢复 %s 失败: %s', e.name, err instanceof Error ? err.stack : String(err))
      }
    }
  }
  if (config.autoRestore) void restore()

  // ============ 自动轮询 watch：build 产物变化 → 自动整包重载 ============
  // watch 源 = 配置 watches + 注入清单（registry）——注入即自动 watch，
  // 自重载后动态 watch 不丢失（registry 持久）；改代码 → build → ~1.5s 自动生效。
  const fingerprints = new Map<string, string>()
  // ⚠️ P1（压测发现③）：目录消失/悬空（junction 指向的源被删/改名）时
  // fingerprintOf 返回 null——若盲目跳过静默，目录反复消失/恢复会产生乒乓
  // reload 且虚增 ✓、无审计。这里抑制重载 + 审计一次（30s 节流防刷屏）。
  const lastDangleTs = new Map<string, number>()
  let reloading = false
  ctx.setInterval(() => {
    if (reloading) return
    const watchList: Array<{ dir: string; match: string }> = [...watches]
    for (const e of readRegistry()) {
      if (!watchList.some(w => w.dir === e.dir)) watchList.push({ dir: e.dir, match: e.name })
    }
    for (const w of watchList) {
      // 防自毁⑤：watch 自动重载永不触发注入器自重载（改注入器代码 → build →
      // 自动自杀无人兜底）；自重载只允许显式 dev_reload_package 调用。
      if (String(w.match).includes('dsh-super-injector')) continue
      const fp = fingerprintOf(join(w.dir, 'lib'))
      if (fp === null) {
        const now = Date.now()
        const prevDang = lastDangleTs.get(w.dir)
        if (prevDang === undefined || now - prevDang > 30000) {
          lastDangleTs.set(w.dir, now)
          auditLog('watch-dangling', `目录不可读，跳过自动重载（源被删/悬空 junction）: ${w.dir}`)
        }
        continue
      }
      lastDangleTs.delete(w.dir)
      const prev = fingerprints.get(w.dir)
      if (prev !== undefined && prev !== fp) {
        fingerprints.set(w.dir, fp)
        // ⚠️ 收紧（用户反馈：太自由容易自杀）：watch 自动重载前**预检新代码
        // 可加载**——build 半途/改错导致的损坏 lib 不可加载时拒绝重载（旧
        // 代码继续跑）+ 审计，而不是盲目重载把自己搞死（与手动自重载的
        // 预检拦截同一道防线）。
        reloading = true
        const libFile = join(w.dir, 'lib', 'index.js')
        const precheck = existsSync(libFile)
          ? ctx.loader.import(pathToFileURL(libFile).href, () => [])
            .then((ns: unknown) => { const probe = ctx.loader.unwrapExports(ns); return !!(probe && (typeof probe === 'function' || typeof probe.apply === 'function')) })
            .catch(() => false)
          : Promise.resolve(false)
        precheck.then((probeOk: boolean) => {
          if (!probeOk) {
            reloading = false
            auditLog('watch-precheck-blocked', `自动重载预检失败（新代码不可加载），保持旧代码: ${w.dir}`)
            logger.warn('[super-injector] 自动重载预检失败，跳过（旧代码继续运行）: %s', w.dir)
            return
          }
          // match 用于 entry 查找，dir 用于 URL 匹配（loadCache key 是 file URL）
          reloadPackage(w.match, w.dir)
            .then(r => logger.info('[super-injector] %s', r))
            .catch(e => logger.warn('[super-injector] %s', e instanceof Error ? e.stack : String(e)))
            .finally(() => { reloading = false })
        })
        return // 一轮只处理一个包，下轮继续
      }
      fingerprints.set(w.dir, fp)
    }
  }, intervalMs)

  // ============ 工具 ============
  // ⚠️ 必须挂 ctx.effect（自己的踩坑记录自己遵守）：裸注册在 fiber 卸载
  // （自重载 dispose/卸载）时不注销 → 残留工具闭包捕获旧 fiber 状态
  // （selfReloading 等）→ 新实例注册撞 duplicate 被跳过 → 跑的是「僵尸
  // 工具的僵尸闭包」（实测：锁永久卡死、新代码永不生效的根因）。
  function safeRegister(tool: any): void {
    try {
      ctx.effect(() => ctx.tools.register(tool), `dsh-super-injector: ${tool.name ?? 'tool'}`)
    } catch (e) {
      logger.warn('[super-injector] 跳过冲突工具注册: %s', e instanceof Error ? e.message : String(e))
    }
  }

  /** 启动自净：清除历史版本裸注册残留的同名工具（僵尸闭包），再注册新工具。 */
  function purgeStaleTools(): void {
    try {
      const toolsSvc = ctx.get('tools') as {
        layers?: { global?: { tools?: Map<string, unknown> } }
        unregister?: (name: string) => unknown
      } | undefined
      if (!toolsSvc) return
      const names: string[] = []
      const table = toolsSvc.layers?.global?.tools
      if (table && typeof table.keys === 'function') {
        for (const name of table.keys()) {
          if (typeof name === 'string' && name.startsWith('dev_')) names.push(name)
        }
      }
      for (const name of names) {
        try {
          if (typeof toolsSvc.unregister === 'function') toolsSvc.unregister(name)
          else if (table) Map.prototype.delete.call(table, name)
        } catch { /* 单项清理失败继续 */ }
      }
      if (names.length > 0) {
        logger.warn('[super-injector] 已清理 %d 个僵尸工具残留: %s', names.length, names.join(','))
        auditLog('purge-stale-tools', names.join(','))
      }
    } catch { /* 自净失败不阻塞 */ }
  }
  purgeStaleTools()

  safeRegister(defineTool({
    name: 'dev_inject_plugin',
    description: '超级模组注入器：运行时注入任意本地 DSH 插件包（junction 链接 + loader.create，不碰 patch/package.json、不重启）。参数 = 插件包目录绝对路径（含 package.json 与 lib/）',
    parameters: {
      dir: { type: 'string', required: true, description: '插件包目录绝对路径（如 F:/dsh/03-dev-infra/dsh-xxx）' },
    },
    output: {
      schema: { type: 'string' },
      render: (_args: unknown, value: unknown) => [{ type: 'text', text: String(value) }],
    },
    async execute(args: { dir: string }) {
      const dir = String(args.dir ?? '').trim()
      if (!dir) return 'ERROR: dir 必填（插件包目录绝对路径）'
      // ⚠️ 注入前 client 骨架校验（2026-08 pixel-forge 事件教训：参考源污染
      // 会把"缺 inject/name"的老坑传播给新插件——注入即检查，有问题先修再注入）
      // 2026-08-14 升级（用户反馈）：①同时检查编译产物 lib/client.js（只有
