        logger.warn('[super-injector] 注入 %s 构建产物可能过期（未阻断）: %s', dir, fresh.warn.join('; '))
      }
      return withOpLock(() => inject(dir))
    },
  }))

  safeRegister(defineTool({
    name: 'dev_injected_list',
    description: '列出已注入的超级模组清单（registry，含目录与时间）',
