  safeRegister(defineTool({
    name: 'dev_clear_routes',
    description: '清 webserver 路由表残留：删除 path 前缀匹配的 exact/prefixes/upgrades 条目（插件热重载残留路由的自愈工具，无需重启）',
    parameters: {
      prefix: { type: 'string', description: 'path 前缀（如 /browser-panel）' },
    },
    output: {
      schema: { type: 'string' },
      render: (_args: unknown, value: unknown) => [{ type: 'text', text: String(value) }],
    },
    async execute(args: { prefix: string }) {
      const hs = ctx.webServer
      const out: string[] = []
      for (const tableName of ['exact', 'prefixes', 'upgrades'] as const) {
        const table = hs?.[tableName]
        if (!table || typeof table.delete !== 'function') {
          out.push(`${tableName}: 不可访问`)
          continue
        }
        const keys = [...table.keys()].filter((k: unknown) => String(k).startsWith(args.prefix))
        for (const k of keys) {
          table.delete(k)
          out.push(`deleted ${tableName}[${k}]`)
        }
        if (!keys.length) out.push(`${tableName}: 无匹配`)
      }
      return out.join('\n')
    },
  }))

  safeRegister(defineTool({
    name: 'dev_reload_package',
    description: '确定性热重载已加载的 bundle 插件包（清缓存 → 重新 import → registry 重建 fiber，失败回滚保留旧代）。不带参数时返回当下已装配插件清单；带参数重载并给出重载前后 fiber 状态对比。',
    parameters: {
      packageName: { type: 'string', description: '包路径子串（缺省 = 只列插件清单，不重载）' },
    },
    output: {
      schema: { type: 'string' },
      render: (_args: unknown, value: unknown) => [{ type: 'text', text: String(value) }],
    },
    async execute(args: { packageName?: string }) {
      if (!args.packageName) {
        return '===== 当前已装配插件（loader entries）=====\n' + listPlugins()
      }
      const entry = findEntry(args.packageName)
      const before = entry ? stateOf(entry) : '（未找到）'
      const result = await withOpLock(() => reloadPackage(args.packageName!))
      // ⚠️ 误报修复（2026-08 实测 "disposed（超时未稳定）" 假象）：重载后
      // loader 可能替换/重建 entry 对象——**旧 entry 引用指向已 dispose 的
      // 旧 fiber**，waitFiberStable 轮询 3 秒都读旧状态 → 误报。必须重新
      // findEntry 拿最新 entry 再查（新 fiber 已挂 entry.fiber，await 已完成）。
      const freshEntry = findEntry(args.packageName)
      const after = freshEntry ? await waitFiberStable(freshEntry) : '（未找到）'
      return result + '\n--- 重载前后状态 ---\nbefore: [' + before + ']\nafter: [' + after + ']'
    },
  }))

  safeRegister(defineTool({
    name: 'dev_reload_preset',
    description: '预设热更新（agent-presets 新一代，绕 ESM 缓存）：给 .agent-presets/<preset>/agent.cordis.yml 的相对 .mjs 引用加 ?v=N query（N 自增）——组合文件指纹变化 → 新会话挂载新一代 → 新 URL 无缓存命中 → 改代码无需换文件名/重启即可生效。已运行会话保持旧代。',
    parameters: {
      preset: { type: 'string', description: '预设 id（缺省 = 全部）' },
    },
    output: {
      schema: { type: 'string' },
      render: (_args: unknown, value: unknown) => [{ type: 'text', text: String(value) }],
    },
    async execute(args: { preset?: string }) {
      const presetsRoot = join(dshHome, '.agent-presets')
      const names = args.preset
        ? [args.preset]
        : (() => { try { return readdirSync(presetsRoot).filter((d) => !d.startsWith('.')) } catch { return [] } })()
      if (!names.length) return 'ERROR: 未找到任何预设（' + presetsRoot + '）'
      const out: string[] = []
      for (const name of names) {
        const ymlFile = join(presetsRoot, name, 'agent.cordis.yml')
        if (!existsSync(ymlFile)) { out.push('[' + name + '] 无 agent.cordis.yml（跳过）'); continue }
        let yml = ''
        try { yml = readFileSync(ymlFile, 'utf8') } catch { out.push('[' + name + '] 读取失败（跳过）'); continue }
        const refRe = /(name: \.\/[A-Za-z0-9._-]+\.mjs)(\?v=\d+)?/g
        const refs = [...yml.matchAll(refRe)]
        if (!refs.length) { out.push('[' + name + '] 无相对 .mjs 引用（无需热更新）'); continue }
        const changed: string[] = []
        for (const m of refs) {
          const base = m[1]
          const cur = m[2] ? Number(m[2].slice(3)) : 0
          yml = yml.replace(m[0], base + '?v=' + (cur + 1))
          changed.push(base.split('/').pop() + ' -> ?v=' + (cur + 1))
        }
        try { writeFileSync(ymlFile, yml, 'utf8') } catch { out.push('[' + name + '] 写入失败（跳过）'); continue }
        out.push('[' + name + '] ' + changed.join(', '))
      }
      return 'OK: 预设热更新\n- ' + out.join('\n- ') + '\n注：新会话挂载新一代（新 URL 绕 ESM 缓存）；已运行会话保持旧代'
    },
  }))

