      try { pkg = JSON.parse(readFileSync(join(pluginDir, 'package.json'), 'utf8')) } catch { return 'ERROR: package.json 解析失败' }
      const version = String(args.version ?? pkg.version ?? '').trim().replace(/^v/, '')
      if (!version) return 'ERROR: 缺版本号'
      const tgzs = readdirSync(pluginDir).filter((f) => f.endsWith('.tgz'))
      if (tgzs.length === 0) return 'ERROR: 目录无 tgz（先 dev_build_plugin）'
      // repo 推断：git remote origin
      let repo = ''
      const remote = runCmd('git', ['remote', 'get-url', 'origin'], pluginDir)
      if (remote && remote.code === 0) {
        const m = /[:/]([^/]+\/[^/]+?)(?:\.git)?\s*$/.exec(remote.output.trim())
        if (m) repo = m[1]
      }
      if (!repo) return 'ERROR: 无法推断仓库（git remote origin）'
      const tgz = join(pluginDir, tgzs[tgzs.length - 1])
      const tag = 'v' + version
      const notesText = String(args.notes ?? `## ${String(pkg.name)} v${version}\n\n由 dsh-super-injector dev_release_plugin 发布。\n\n### 安装\n\n下载 tgz 解压 → 注入器环境内 \`dev_inject_plugin <目录>\`，或 \`dsh plugin --profile web add <目录>\`。`)
      const notesFile = join(pluginDir, '.release-notes-' + Date.now() + '.md')
      writeFileSync(notesFile, notesText, 'utf8')
      const r = runCmd('gh', ['release', 'create', tag, tgz, '--repo', repo, '--title', `${String(pkg.name)} v${version}`, '--notes-file', notesFile], pluginDir)
      try { rmSync(notesFile, { force: true }) } catch { /* 忽略 */ }
      if (r === null) return 'ERROR: gh CLI 不可用（需在 PATH 且已认证）——手动：\ngh release create ' + tag + ' ' + tgz + ' --repo ' + repo + ' --notes "<说明>"'
      if (r.code !== 0) return `ERROR: gh release 失败（exit ${r.code}）:\n${r.output.slice(-800)}`
      const url = /(https:\/\/github\.com\/[^\s]+)/.exec(r.output)
      auditLog('release', `${String(pkg.name)} ${tag} → ${repo}`)
      return 'OK: ' + String(pkg.name) + ' ' + tag + ' 已发布' + (url ? '\n' + url[1] : '') + '\n' + r.output.slice(-400)
    },
  }))

  safeRegister(defineTool({
    name: 'dev_self_test',
    description: '故障演练：一键回归注入器全链路——①注入假插件→host ✓ ②热重载→fiber uid 变化 ③自重载节流拒绝（<10s）④预检拦截（临时破坏 lib→拒绝自杀→恢复）⑤卸载即净 ⑥patch 写入合法性。全部自恢复、不留下污染；输出 PASS/FAIL 清单。',
    parameters: {},
    output: {
      schema: { type: 'string' },
      render: (_args: unknown, value: unknown) => [{ type: 'text', text: String(value) }],
    },
    async execute() {
      const results: Array<[string, boolean, string]> = []
      const check = (name: string, ok: boolean, detail = ''): void => { results.push([name, ok, detail]) }
      // ⚠️ 测试插件**固定 specifier + 固定目录**：tsx 的 resolve 缓存按 specifier
      // 记忆解析路径——换名/换目录会命中旧缓存（ENOENT 旧路径，实测踩坑）。
      // 目录取 DSH_HOME 下稳定路径（不硬编码盘符/用户名，随部署走），
      // 首次解析后缓存永远一致。
      const TEST_PKG = '@dsh-external/selftest-runner'
      const TEST_SHORT = 'selftest-runner'
      const tmpDir = join(dshHome, 'super-injector', TEST_SHORT)
      try { rmSync(tmpDir, { recursive: true, force: true }) } catch { /* 忽略 */ }
      mkdirSync(tmpDir, { recursive: true })
      try {
        // ── 1. 生成最小测试插件（工具形态）──
        mkdirSync(join(tmpDir, 'src'), { recursive: true })
        mkdirSync(join(tmpDir, 'scripts'), { recursive: true })
        writeFileSync(join(tmpDir, 'package.json'), JSON.stringify({
          name: TEST_PKG, version: '0.0.1', private: true, type: 'module',
          main: './lib/index.js', files: ['lib'], license: 'BSD-3-Clause',
          peerDependencies: { '@deepseek-ai/dsh-tools': '>=0.0.1-rc <2', 'cordis': '>=4.0.0-rc <5' },
          devDependencies: { '@types/node': '^24.13.3', typescript: '^5.9.0' },
          scripts: { build: 'bash scripts/build.sh' },
        }, null, 2) + '\n', 'utf8')
        writeFileSync(join(tmpDir, 'tsconfig.json'), '{\n  "compilerOptions": {\n    "target": "ES2023", "module": "NodeNext", "moduleResolution": "NodeNext", "lib": ["ES2023"],\n    "strict": true, "types": ["node"], "declaration": true, "declarationDir": "lib/types",\n    "outDir": "lib", "rootDir": "src", "skipLibCheck": true, "esModuleInterop": true,\n    "sourceMap": true\n  },\n  "include": ["src"]\n}\n', 'utf8')
        writeFileSync(join(tmpDir, 'src', 'index.ts'), `import type { Context } from '@deepseek-ai/cordis'\nimport { defineTool } from '@deepseek-ai/dsh-tools'\nexport const name = ${JSON.stringify(TEST_PKG)}\nexport const inject = ['tools']\nexport function apply(ctx: Context): void {\n  ctx.effect(() => ctx.tools.register(defineTool({\n    name: 'self_test_hello',\n    description: 'self test',\n    parameters: {},\n    output: { schema: { type: 'string' }, render: (_a: unknown, v: unknown) => [{ type: 'text', text: String(v) }] },\n    async execute() { return 'hello' },\n  })), 'self-test')\n}\n`, 'utf8')
        writeFileSync(join(tmpDir, 'scripts', 'build.sh'), `#!/bin/bash\nset -euo pipefail\nROOT="$(cd "$(dirname "$0")/.." && pwd)"\ncd "$ROOT"\nCHECKOUT="\${DSH_CHECKOUT:-}"\nif [ -z "$CHECKOUT" ] || [ ! -d "$CHECKOUT/packages" ]; then echo "no checkout" >&2; exit 1; fi\nTSC="$CHECKOUT/node_modules/.bin/tsc"\nlink_pkg() {\n  node -e "const fs=require('fs');const path=require('path');const l=path.resolve(process.argv[1]);const t=path.resolve(process.argv[2]);fs.rmSync(l,{recursive:true,force:true});fs.mkdirSync(path.dirname(l),{recursive:true});fs.symlinkSync(t,l,process.platform==='win32'?'junction':'dir');" "node_modules/$1" "$2"\n}\nmkdir -p node_modules/@deepseek-ai\nnode -e "const fs=require('fs');fs.rmSync('node_modules/@standard-schema',{recursive:true,force:true})"\nlink_pkg @deepseek-ai/cordis "$CHECKOUT/vendor/cordis"\nlink_pkg @deepseek-ai/cosmokit "$CHECKOUT/vendor/cosmokit"\nlink_pkg @deepseek-ai/schemastery "$CHECKOUT/vendor/schemastery"\nlink_pkg @deepseek-ai/dsh-tools "$CHECKOUT/packages/core/tools"\nlink_pkg @types/node "$CHECKOUT/node_modules/@types/node"\n"$TSC" -p tsconfig.json\n`, 'utf8')
        const checkout = detectCheckout()
        if (!checkout) { check('checkout 探测', false, '无 DSH_CHECKOUT'); return summarize(results) }
        // ── 2. 构建测试插件 ──
        const bash = findBash()
        if (!bash) { check('bash 探测', false, '无 bash'); return summarize(results) }
        const bashBinDir = bash !== 'bash' ? dirname(bash) : ''
        const sep = process.platform === 'win32' ? ';' : ':'
        const buildEnv: Record<string, string> = { DSH_CHECKOUT: checkout }
        buildEnv.PATH = [bashBinDir, dirname(process.execPath), process.env.PATH ?? ''].filter(Boolean).join(sep)
        const br = runCmd(bash, ['scripts/build.sh'], tmpDir, buildEnv)
        const libBuilt = existsSync(join(tmpDir, 'lib', 'index.js'))
        check('测试插件构建', br !== null && br.code === 0 && libBuilt, br && br.code !== 0 ? br.output.slice(-300) : (libBuilt ? '' : 'lib/index.js 未生成'))
        if (!br || br.code !== 0 || !libBuilt) return summarize(results)
        // ── 3. 注入 → host ✓ ──
        // ⚠️ 先清理上次自检可能的残留（整体 FAIL 中断时 finally 不一定跑完——
        // 实测：注入报「已激活运行」因为残留 entry 没卸载）
        try { await uninject(TEST_SHORT) } catch { /* 忽略 */ }
        const inj = await inject(tmpDir)
        if (inj.includes('host ✓')) {
          check('注入（host ✓）', true, inj)
        } else {
          let diag = ''
          try { diag += 'junction→' + readlinkSync(join(profileNodeModules, '@dsh-external', TEST_SHORT)) + '\n' } catch (e) { diag += 'junction err: ' + (e as { code?: string }).code + '\n' }
          diag += 'tmpLib=' + existsSync(join(tmpDir, 'lib', 'index.js')) + ' tmpPkg=' + existsSync(join(tmpDir, 'package.json')) + ' tmpSrc=' + existsSync(join(tmpDir, 'src', 'index.ts'))
          check('注入（host ✓）', false, inj + '\n' + diag)
        }
        // ── 4. 热重载 → fiber uid 变化（自包含：重载 selftest-runner 自身。
        //    固定 specifier + 固定目录 → 缓存一致；不依赖外部插件）──
        const beforeUid = (() => { for (const e of ctx.loader.entries()) { const o = e.options; if (!o.group && String(o.name) === TEST_PKG && e.fiber) return e.fiber.uid } return null })()
        try {
          // 确保模块在缓存（purge 旧 key + 重新 import——固定目录解析一致）
          const lcT = ctx.loader.internal?.loadCache as Map<string, unknown> | undefined
          if (lcT) {
            for (const u of [...lcT.keys()]) {
              if (typeof u === 'string' && decodeURIComponent(u).includes(TEST_SHORT)) Map.prototype.delete.call(lcT, u)
            }
          }
          await ctx.loader.import(TEST_PKG, () => [])
        } catch { /* import 失败不阻塞（注入已加载） */ }
        const rl = await withOpLock(() => reloadPackage(TEST_SHORT, tmpDir))
        const afterUid = (() => { for (const e of ctx.loader.entries()) { const o = e.options; if (!o.group && String(o.name) === TEST_PKG && e.fiber) return e.fiber.uid } return null })()
        check('热重载（uid 变化）', beforeUid !== null && afterUid !== null && beforeUid !== afterUid, `uid ${beforeUid} → ${afterUid} | ${rl.slice(0, 80)}`)
        // ── 5. 自重载节流（不真自杀：伪造时间戳）──
        writeSelfReloadState(Date.now() - 5000)
        const throttle = await withOpLock(() => reloadPackage('dsh-super-injector'))
        check('自重载节流（<10s 拒绝）', throttle.includes('节流'), throttle.slice(0, 100))
        writeSelfReloadState(0)
        // ── 6. 预检拦截（临时破坏**实际运行**的注入器 lib → 拒绝自杀 → 恢复）──
        // ⚠️ 通用定位（实测踩坑×2）：①注入器可能运行于副本目录（cloud-restore
        // 等）——破坏本地工作区 lib 不会让预检拦截；②loadCache key 是 realpath
        // （不含包名）——按包名扫不到。可靠方案：junction 的 realpath（junction
        // 由安装建立、始终指向实际运行文件）。
        let libPath = ''
        try {
          const juncLib = join(profileNodeModules, '@dsh-external', 'dsh-super-injector', 'lib', 'index.js')
          if (existsSync(juncLib)) {
            const real = realpathSync(juncLib)
            if (existsSync(real)) libPath = real
          }
          if (!libPath) {
            // fallback：loadCache 扫描（含包名或 cloud-restore 特征）
            const lcT = ctx.loader.internal?.loadCache as Map<string, unknown> | undefined
            for (const u of lcT?.keys() ?? []) {
              if (typeof u !== 'string' || !u.endsWith('/lib/index.js')) continue
              const d = decodeURIComponent(u)
              if (!d.includes('dsh-super-injector') && !d.includes('cloud-restore')) continue
              let fp = d.replace(/^file:\/\//, '')
              if (fp.startsWith('/')) fp = fp.slice(1)
              if (existsSync(fp)) { libPath = fp; break }
            }
          }
        } catch { /* 定位失败按无处理 */ }
        if (libPath) {
          let libRestored = true
          try {
            const backup = readFileSync(libPath, 'utf8')
            writeFileSync(libPath, 'BROKEN SELF TEST !!!', 'utf8')
            const precheck = await withOpLock(() => reloadPackage('dsh-super-injector'))
            check('预检拦截（拒绝自杀）', precheck.includes('预检失败'), precheck.slice(0, 150))
            writeFileSync(libPath, backup, 'utf8')
            libRestored = true
          } catch (e) {
            check('预检拦截（拒绝自杀）', false, String(e))
          }
          check('预检后 lib 恢复', libRestored)
        } else {
          check('预检拦截（拒绝自杀）', false, '未定位注入器 lib')
        }
        // ── 7. 卸载即净 ──
        const ui = await uninject(TEST_SHORT)
        let entryGone = true
        for (const e of ctx.loader.entries()) { const o = e.options; if (!o.group && String(o.name) === TEST_PKG) entryGone = false }
        check('卸载即净（entry 移除）', entryGone, ui.slice(0, 100))
        // ── 8. patch 写入合法性（writePatch → 防「[] 与列表混存」双顶层值）──
        const patched = writePatch(`\n# self-test ${Date.now()}\n- id: self-test-check\n  disabled: true\n`)
        const patchText = readFileSync(join(dirname(profileNodeModules), 'cordis.patch.yml'), 'utf8')
        const hasBareArray = /^\s*\[\]\s*$/m.test(patchText)
        const hasList = /^\s*- id:/m.test(patchText)
        const patchValid = !(hasBareArray && hasList)
        check('patch 写入（无 [] 与列表混存）', patched && patchValid, `bareArray=${hasBareArray} list=${hasList}`)
        // 清理测试条目（self-test-check + selftest-runner disabled），
        // ⚠️ 仅当 patch 为空时恢复 []（有列表条目时不能追加 []——双顶层，实测踩坑）
        try {
          let cleaned = patchText
          cleaned = cleaned.replace(/\n# self-test \d+\n- id: self-test-check\n  disabled: true\n?/, '')
          cleaned = cleaned.replace(/\n# 已卸载插件（[^\n]*\n- id: selftest-runner\n  disabled: true\n?/, '')
          const stillEntries = /^\s*- id:/m.test(cleaned)
          const finalPatch = stillEntries
            ? cleaned
            : cleaned.replace(/^\s*\[\]\s*$/m, '') + '\n[]\n'
          writeFileSync(join(dirname(profileNodeModules), 'cordis.patch.yml'), finalPatch, 'utf8')
        } catch { /* 清理失败不阻塞 */ }
      } catch (e) {
        check('整体', false, String(e))
      } finally {
        // 保留 tmpDir 目录（junction 目标稳定，Node resolve 缓存一致性）；
        // 仅清理可能残留的 junction（卸载路径已处理，这里兜底）
        try {
          const linkDir = join(profileNodeModules, '@dsh-external', TEST_SHORT)
          if (existsSync(linkDir)) rmSync(linkDir, { recursive: true, force: true })
        } catch { /* 忽略 */ }
      }
      return summarize(results)
    },
  }))

  /** 汇总 PASS/FAIL（PASS 项的预期拒绝场景（ERROR: 前缀）显示为 [EXPECTED]）。 */
  function summarize(results: Array<[string, boolean, string]>): string {
    const pass = results.filter(([, ok]) => ok).length
    const lines = results.map(([n, ok, d]) => {
      let detail = d ? d.slice(0, 400) : ''
      if (ok && detail.startsWith('ERROR:')) detail = '[EXPECTED]' + detail.slice(6)
      return `- [${ok ? 'PASS' : 'FAIL'}] ${n}${detail ? ' — ' + detail : ''}`
    })
    auditLog('self-test', `PASS ${pass}/${results.length}`)
    return `===== 注入器自检（PASS ${pass}/${results.length}）=====\n` + lines.join('\n')
  }

  // ============ 静态能力提示注入（缓存原则：静态到头、动态到尾）============
  // - 静态内容（身份/能力声明，编译期常量）→ order 靠前（头部）：tools schema
  //   变更（注入/转正工具）时静态段仍在缓存前缀内，只伤 schema 之后；
  // - 动态内容（记忆检索/实时状态）→ 严禁进 system 头部：走消息尾追加
  //   （尾部注入插件即此模式）或 system 最尾，变化只伤自身之后；
  // - 本段 text 必须保持编译期常量——任何每轮变化的动态拼接都会全灭前缀缓存。
  // ⚠️ 容忍重复注册（实测：自重载 rebuild 时旧 entry 的 context 可能残留，
  // duplicate 会让 apply 整体 failed → 注入器死亡 + 自愈 3 连败）。duplicate
  // 时跳过注册（新实例可运行），比 failed 强。
  try {
    ctx.systemPrompt.context({
      name: 'dsh-super-injector',
      order: -90,
      // 引导（首次接触的 agent 从这段获得完整认知）：
      // 1) dev_* 工具 = dsh-super-injector（运行时注入通道）；
      // 2) 插件形态无上限：工具包 / 守护循环（timer+LLM 自主 agent loop）/
    //    UI 面板 / 混合形态，同一通道——注入即完整生效（host+UI）、可热
    //    重载与自重载、卸载即净；
    // 3) 插件自身的提示词/工具/循环皆可自我优化（改→build→重载闭环）；
    // 4) 资源复用：建新插件优先克隆/借鉴/重构生态已有资源（dsh-external
    //    仓库、已注入插件、官方 packages 的服务面与构建模式），不重复造轮子；
    // 5) 使命：若注入器无法支撑此闭环，优先修复注入器。
    // ⚠️ 静态常量文本（缓存原则：静态到头）——严禁动态拼接。
    text: '本环境装有 dsh-super-injector（dev_* 工具）：任意本地插件包可运行时注入——工具包/守护循环（timer+LLM 自主 agent loop）/UI 面板/混合形态，同一通道；注入即完整生效（host+UI）、可热重载与自重载、卸载即净。插件自身的提示词/工具/循环皆可自我优化；建新插件优先克隆/借鉴/重构生态已有资源（dsh-external 仓库、已注入插件、官方 packages 模式），不重复造轮子。若注入器无法支撑此闭环，优先修复注入器。从零体验路径：dev_plugin_status → dev_self_test → dev_scaffold_plugin → dev_build_plugin → dev_inject_plugin → dev_uninject_plugin。',
    })
  } catch (e) {
    logger.warn('[super-injector] systemPrompt.context 重复注册容忍（跳过，新实例继续运行）: %s', e instanceof Error ? e.message : String(e))
  }

  logger.info('[super-injector] 就绪：watch %d 目录（%dms），autoRestore=%s', watches.length, intervalMs, String(config.autoRestore))
  // B: 每次装配后仲裁——幽灵压制官方时自动清理恢复（含历史残留场景）
  arbitrateOfficial()

  // ⚠️ client-modules pkgMeta 缓存自愈（实测）：bundle 装配的插件在
  // client-modules 首次扫描时 junction 可能未建 → resolvePkgJson 抛 →
  // pkgMeta 缓存 null（进程级永久，无官方清缓存 API）→ client 永不注册
  // （设置页「插件」不出现）。junction 已建立后：清缓存 + 重解析注册。
  try {
    const cmSvc = ctx.get('clientModules') as {
      pkgMeta?: Map<string, unknown>
      processOne?: (name: string) => unknown
    } | undefined
    if (cmSvc?.pkgMeta && typeof cmSvc.pkgMeta.delete === 'function') {
      cmSvc.pkgMeta.delete('@dsh-external/dsh-super-injector')
      if (typeof cmSvc.processOne === 'function') {
        cmSvc.processOne('@dsh-external/dsh-super-injector')
        auditLog('client-meta-healed', 'client-modules pkgMeta 缓存已清并重解析（设置页插件管理 UI 注册）')
      }
    }
  } catch { /* 缓存自愈失败不阻塞 */ }

  // ═══════════════════════════════════════════════════════════════════
  // 插件管理 UI API（settings.section 页面后端）
  // 端点：GET /list（registry+状态+统计）、POST /uninstall{match}、
  //       POST /inject{dir}、POST /ingest{dir,title}（新建会话内化）
  // ═══════════════════════════════════════════════════════════════════
  async function readBody(req: any): Promise<string> {
    const chunks: Buffer[] = []
    for await (const c of req) chunks.push(Buffer.from(c))
    return Buffer.concat(chunks).toString('utf8')
  }

  /** 新建 agent 会话，把任意目录内化成插件（AI 自主完成分析→脚手架→构建→注入）。 */
  async function startIngest(dir: string, title?: string): Promise<string> {
    const abs = resolve(dir)
    if (!existsSync(abs)) return 'ERROR: 目录不存在: ' + abs
    const agentsSvc = ctx.get('agents') as { create?: (options: any) => Promise<{ agent: { id: string } }> } | undefined
    if (!agentsSvc || typeof agentsSvc.create !== 'function') return 'ERROR: agents 服务不可用（无法新建会话）'
    const sessionId = 'ingest-' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6)
    const prompt = `请把目录 ${abs} 里的内容**内化成 DSH 插件**。步骤：①分析内容（代码/脚本/配置/文档/资源，任意形态）②决定插件形态（toolkit 工具包 / daemon-loop 守护循环 / ui-panel UI 面板 / hybrid 混合）③用 dev_scaffold_plugin 生成骨架或直接编写插件包（package.json/tsconfig/scripts/build.sh/src）④dev_build_plugin 构建⑤dev_inject_plugin 注入⑥dev_self_test 自检确认。若内容本身已是可注入插件包（含 package.json+lib/）则直接构建注入。完成后汇报插件名与用途。`
    const seed = [{
      type: 'user/message',
      seq: 0,
      time: Date.now(),
      // ⚠️ user/message 的 data 就是消息本体（dsh-session 事件契约），不能包一层
      // `message:`——嵌套形状会让 router-standard 的 sessionMode 提取不到文本，
      // 插件生成的首条消息被误判 weak（router-standard issue #1 联动修复）。
      data: {
        kind: 'user',
        source: { kind: 'user' },
        content: [{ type: 'text', text: prompt }],
      },
    }]
    const handle = await agentsSvc.create({
      sessionId,
      meta: { cwd: process.cwd() },
      seed,
    })
    auditLog('ingest-session', `${abs} → 会话 ${handle.agent.id}（${title ?? '内化插件'}）`)
    return `OK: 内化会话已创建（${handle.agent.id}）——AI 正在把内容变成插件，会话列表可见`
  }

  ctx.effect(() => ctx.webServer.register({
    kind: 'prefix',
    path: '/super-injector/api',
    handler: async (req: any, res: any) => {
      const send = (code: number, obj: unknown): void => {
        res.writeHead(code, { 'content-type': 'application/json; charset=utf-8' })
        res.end(JSON.stringify(obj))
      }
      try {
        const url = new URL(req.url ?? '/', 'http://localhost')
        const path = url.pathname.replace(/^\/super-injector\/api/, '') || '/'
        if (req.method === 'GET' && path === '/list') {
          const entries = readRegistry().map((e) => ({ ...e, active: hasActiveEntry(e.name) }))
          return send(200, { ok: true, entries, stats: opStats, clientDeclared: !!process.env.DSH_WEB })
        }
        if (req.method === 'POST' && path === '/uninstall') {
          const body = JSON.parse(await readBody(req))
          const match = String(body?.match ?? '').trim()
          if (!match) return send(400, { ok: false, error: 'match 必填' })
          const result = await uninject(match)
          return send(200, { ok: true, result })
        }
        if (req.method === 'POST' && path === '/inject') {
          const body = JSON.parse(await readBody(req))
          const dir = String(body?.dir ?? '').trim()
          if (!dir) return send(400, { ok: false, error: 'dir 必填' })
          const result = await inject(dir)
          return send(200, { ok: true, result })
        }
        if (req.method === 'POST' && path === '/ingest') {
          const body = JSON.parse(await readBody(req))
          const dir = String(body?.dir ?? '').trim()
          if (!dir) return send(400, { ok: false, error: 'dir 必填（要内化成插件的文件夹路径）' })
          const result = await startIngest(dir, String(body?.title ?? ''))
          return send(200, { ok: true, result })
        }
        return send(404, { ok: false, error: 'not found: ' + path })
      } catch (e) {
        return send(500, { ok: false, error: String(e instanceof Error ? e.message : e) })
      }
    },
  }), 'super-injector: plugin-manager-api')
}
"
    },
    {
      "path": "graded/src/tools.js",
      "content": "/**
 * tools — 分级模式 v4 的三个语义化工具（agent 层注册,不污染全局）。
 *
 *   edit_plan   按层级编辑树（level 参数切语义：'L1' 大类列表 / 'L2' 完整树）
 *   lock_stage  锁定当前层级（level 参数；锁了就是锁了——已锁层 edit 被拒）
 *   mark_task   开发期标定完成（level/title/status；标注后 pre-step 自动注入下一个小类）
 *
 * 数据面（todo max）：清单只存在于结构化状态（plan.groups）与工具结果文本,
 * 不写官方 todo_write；自定义事件不落盘（DSH 会话加载器只认白名单事件类型,
 * 库外插件事件会被判 SessionFormatUnsupportedError）。
 *
 * Schema 形态约束（血泪坑,勿改）：
 *   register() 用 assertSupportedJsonSchema 直查 output.schema 原文,发给模型的
 *   parameters 经服务端 JSON Schema 严格校验——全都只认标准 raw 形态：
 *   对象级 required 数组,属性级一律不允许 required 键。
 *
 * definition 由 index.js 构造（execute 需要 apply 作用域的 state/事件/ask 依赖）：
 *   editPlanDefinition(deps) / lockStageDefinition(deps) / markTaskDefinition(deps)
 *   deps = { getState(sid), setState(sid, s), askUser(agent, state) }
 */

import {
  assertL1Items, assertL2Groups, onEditL1, onEditL2, onLockL1, onLockL2,
  onReviewApproved, onReviewRejected, onMark, onCommitStar, onRedteamVerdict, onReviseDo,
  treeText, groupDone, loadConceptLimit, loadVerifyMode, allDone, currentFocus,
  trigger, initMode, loadState, saveState,
} from './mode-state.js'
import { focusL2, focusL2GroupOpen, focusL2Last, groupCheck, finalCheck, phaseL2, reviewPendingText, specSheet } from './inject-text.js'

const TEXT = (text) => ([{ type: 'text', text: String(text) }])

/** 打卡续轮防爆计数（同一小类最多自动续轮 2 次；热重载清空不致命,最坏多续一轮） */
const deferCounts = new Map()

const outputSpec = {
  schema: {
    type: 'object', additionalProperties: false, required: ['ok', 'text'],
    properties: {
      ok: { type: 'boolean' },
      text: { type: 'string' },
      warnings: { type: 'array', items: { type: 'string' }, description: '软约束提示（如概念超限），非错误' },
    },
  },
  render: (_args, value) => TEXT(value.text + (value.warnings?.length ? `\n（提示：${value.warnings.join('；')}）` : '')),
}

/* 标准 raw JSON Schema 子节点（无属性级 required 键）；3.1 小类规格化：spec/accept/do/verify 必填 */
const groupItemSchema = {
  type: 'object', additionalProperties: false, required: ['title', 'spec', 'accept', 'do', 'verify'],
  properties: {
    title: { type: 'string', description: '小类名（纯名词短语,不要重复大类词）' },
    concepts: { type: 'array', items: { type: 'string' }, description: `核心概念（≤${loadConceptLimit(null)} 个——面板设置实时值；超限仅提示非错误）` },
    spec: { type: 'string', description: '小类任务说明（多行；可提及参考文档/文件，注入时自然引用）' },
    accept: { type: 'array', items: { type: 'string' }, description: '验收标准（按模式文法：correct=可测量断言/experience=感受断言+可复现动作/research=可复核断言;探索型须带退路占位）' },
    mode: { type: 'string', enum: ['correct', 'experience', 'research'], description: '本小类验收模式（可缺省=继承会话模式——全栈任务可按小类粒度换重心）' },
    do: { type: 'string', enum: ['self', 'subagent', 'workflow', 'daemon', 'mixed'], description: '开发增量执行形态（选项内自主抉择,注入给摘要）' },
    verify: { type: 'string', enum: ['self', 'subagent', 'redteam', 'dual', 'workflow'], description: '验证执行形态（开发期只读；redteam 走裁决门）' },
  },
}
const groupSchema = {
  type: 'object', additionalProperties: false, required: ['title', 'items'],
  properties: {
    title: { type: 'string', description: '大类名（须与已锁定的大类一致）' },
    spec: { type: 'string', description: '组任务描述（可选；缺省保留 L1 已定值）' },
    accept: { type: 'array', items: { type: 'string' }, description: '组级验收标准（可选；缺省保留 L1 已定值）' },
    verify: { type: 'string', enum: ['self', 'subagent', 'redteam', 'user'], description: '组收官验证方（可选；缺省保留 L1 已定值）' },
    items: { type: 'array', items: groupItemSchema },
  },
}

/** 软约束提示采集（概念上限为提示级约束，不阻断；上限=loadConceptLimit 面板设置）。 */
function collectWarnings(level, args, sid) {
  const out = []
  if (level === 'L2') {
    const limit = (() => { try { return loadConceptLimit(sid) } catch { return 3 } })()
    for (const g of (args?.groups || [])) {
      for (const it of (g?.items || [])) {
        const n = (it?.concepts || []).length
        if (n > limit) out.push(`「${g?.title || ''}/${it?.title || ''}」概念超限 ${n} > ${limit}（仅提示，不阻断）`)
      }
    }
  }
  return out
}

/**
 * commit_star：头脑风暴定稿（3.1）。purpose 必填（北极星目的宣言）；
 * 校验：不得照抄任务原文、不得过短敷衍；brainstorm/l1-edit/l2-edit/review 可定稿或修订，
 * develop/final 只读（星象已在规约中，改口回『修改』）。
 */
export function commitStarDefinition() {
  return {
    name: 'commit_star',
    description: '【分级·定稿】头脑风暴定稿：purpose=北极星目的宣言（必填，一句话：为谁/处境/价值/可观测结果，不得照抄任务原文）；requirements=对齐后需求；nonGoals=非目标；assumptions=假设；mode=脑暴模式题的选择（correct/experience/research，随定稿落盘为会话模式）。定稿后进入大类规划（edit_plan L1）。开发前可再次调用=修订。',
    parameters: {
      type: 'object', additionalProperties: false, required: ['purpose'],
      properties: {
        purpose: { type: 'string', description: '北极星：一句话目的宣言（为【谁】在【什么处境】下达成【什么价值/可观测结果】）' },
        requirements: { type: 'array', items: { type: 'string' }, description: '需求条目（对齐后）' },
        nonGoals: { type: 'array', items: { type: 'string' }, description: '非目标/不做清单' },
        assumptions: { type: 'array', items: { type: 'string' }, description: '假设（默认理解与采纳方式）' },
        mode: { type: 'string', enum: ['correct', 'experience', 'research'], description: '脑暴模式题的用户选择（随定稿落盘为会话验收模式；不传=保持当前）' },
      },
    },
    output: outputSpec,
    async execute(args, exec) {
      const sid = exec?.agent?.session?.id
      if (!sid) throw new Error('commit_star 需要会话')
      let s = loadState(sid) || initMode() // 磁盘权威（代际免疫）
      const { purpose, requirements, nonGoals, assumptions, mode } = args || {}
      // 阶段只读优先（语义最明确：不该调用的阶段先报阶段，再谈内容）
      const editable = s.stage === 'brainstorm' || s.stage === 'l1-edit' || s.stage === 'l2-edit' || s.stage === 'review'
      if (!editable && s.stage !== 'off') throw new Error('开发/终验阶段星象只读（北极星已入规约；改口走『修改』回审）。')
      const p = String(purpose || '').trim()
      if (!p) throw new Error('commit_star 需要 purpose：北极星目的宣言（必填）')
      const task = String(s.task || '').trim()
      if (task && (p === task || p.includes(task))) throw new Error('purpose 不得机械照抄任务原文：须用"为谁/处境/价值/结果"句式重新表述（对齐后）。')
      if (p.length < 12) throw new Error('purpose 过短（<12 字）：请给出有信息量的目的宣言，而非口号。')
      let auto = false
      if (s.stage === 'off') {
        // 模型自主进入（3.1）：off → 写目的宣言即激活（脑暴链一次对齐；/graded 非必需）
        s = trigger(initMode(), `（模型自主进入）${p.slice(0, 60)}`)
        auto = true
      }
      const finalized = onCommitStar(s, { purpose: p, requirements, nonGoals, assumptions })
      // v3.2：脑暴模式题选择随定稿落盘（唯一可信的会话模式来源）
      if (mode && ['correct', 'experience', 'research'].includes(mode)) finalized.mode = mode
      saveState(sid, finalized)
      const cur = loadState(sid) || s
      return {
        ok: true,
        text: auto
          ? `⭐ 模型自主进入分级模式（未 /graded 亦激活）——脑暴已由目的宣言一次对齐：\n${p}\n需求 ${cur.star.requirements.length} 条 / 非目标 ${cur.star.nonGoals.length} 条 / 假设 ${cur.star.assumptions.length} 条\n进入大类规划：edit_plan(level="L1", items[].title 一行一个大类,组 spec/accept 必填)。\n（信息缺口将按"默认理解"写入 assumptions——用户随时可 [模式:xxx] 或评语补正）`
          : `⭐ 北极星已定稿：${p}\n需求 ${cur.star.requirements.length} 条 / 非目标 ${cur.star.nonGoals.length} 条 / 假设 ${cur.star.assumptions.length} 条——进入大类规划：edit_plan(level="L1", items[].title 一行一个大类)。`,
      }
    },
    presentCall: (args) => ({ card: 'generic', title: '脑暴定稿 (commit_star)', kind: 'other', rawInput: args }),
  }
}

/**
 * redteam_verdict：红队裁决（3.1）。仅 verify=redteam 的小类/组可用；
 * reject 必须附问题清单（issues 非空）；reject → 修复后**必须再次裁决**（再审批义务,自演红队同流程）；
 * pass 后 mark_task 才可推进（门由组合流程层执行）。轮次/log 落盘（面板消费）。
 */
export function redteamVerdictDefinition() {
  return {
    name: 'redteam_verdict',
    description: '【分级·红队】对 verify=redteam 的项做裁决（冷视角打脸）：level=L1 组级/L2 小类级，title 精确匹配；verdict=pass 通过 / reject 打回（打回必须附 issues 问题清单）；打回后修复必须再次裁决（再审批,自演同流程）。裁决轮次与日志落盘。',
    parameters: {
      type: 'object', additionalProperties: false, required: ['level', 'title', 'verdict'],
      properties: {
        level: { type: 'string', enum: ['L1', 'L2'], description: '裁决层级：L1 组级（组收官）/ L2 小类级' },
        title: { type: 'string', description: '要裁决的类名（精确匹配）' },
        verdict: { type: 'string', enum: ['pass', 'reject'], description: '通过 / 打回' },
        issues: { type: 'array', items: { type: 'string' }, description: '问题清单（reject 必填,每条=证据/行号/建议）' },
      },
    },
    output: outputSpec,
    async execute(args, exec) {
      const { level, title, verdict, issues } = args || {}
      const sid = exec?.agent?.session?.id
      const s = loadState(sid) || initMode() // 磁盘权威（代际免疫）
      if (!sid || !s || (s.stage !== 'develop' && s.stage !== 'final')) {
        throw new Error('redteam_verdict 仅在开发/终验阶段可用（审核通过后）')
      }
      if (verdict !== 'pass' && verdict !== 'reject') throw new Error('verdict 必须是 pass 或 reject')
      if (verdict === 'reject' && !(Array.isArray(issues) && issues.some((x) => String(x || '').trim()))) {
        throw new Error('reject 必须附问题清单（issues 至少一条：证据/行号/建议）')
      }
      const res = onRedteamVerdict(s, level, title, verdict, issues)
      if (!res.ok) throw new Error(res.error)
      saveState(sid, res.state)
      const cur = loadState(sid) || res.state
      const node = level === 'L1'
        ? (cur.plan.groups || []).find((g) => g.title === title)
        : (cur.plan.groups || []).flatMap((g) => g.items || []).find((it) => it.title === title)
      const rt = node?.redteam || {}
      const head = verdict === 'pass' ? '✅ 红队裁决：通过' : '⭕ 红队裁决：打回'
      const extra = verdict === 'reject' ? `——修复后**必须再次裁决**（再审批义务：改一次不算过,经过再算过）。` : ''
      return { ok: true, text: `${head}「${title}」轮次=${rt.rounds}${extra}\n问题清单：${(rt.log?.[rt.log.length - 1]?.issues || []).join('；') || '（无）'}` }
    },
    presentCall: (args) => ({ card: 'generic', title: `红队裁决 (redteam_verdict ${args?.level || ''} ${args?.title || ''})`, kind: 'other', rawInput: args }),
  }
}

/**
 * revise_do：开发期执行形态修订（3.1）。do 可改（登记 doHistory）；
